document.write("\r\n\r\n</head>\r\n<body>\r\n\r\n<!-- AUTH PAGE -->\r\n<div class=\"auth-page\" id=\"authPage\">\r\n  <div class=\"auth-card\">\r\n    <div class=\"auth-logo-wrap\">\r\n      <div class=\"auth-logo-icon\">\r\n        <img src=\"data:image/png;base64,\" alt=\"Hether logo\" style=\"width:100%;height:100%;object-fit:contain;\">\r\n      </div>\r\n      <span class=\"auth-logo-name\">hether</span>\r\n    </div>\r\n\r\n    <div class=\"auth-panel\">\r\n      <div class=\"auth-panel-view active\" id=\"authLanding\">\r\n        <div class=\"auth-panel-title\">Tune into <span class=\"gradient-text\">Your Favourites</span></div>\r\n        <div class=\"auth-landing-btns\">\r\n          <button class=\"auth-main-btn primary\" onclick=\"showAuthView('login')\">\r\n            Log in\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"14\" height=\"14\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n          </button>\r\n          <div class=\"auth-divider\"><div class=\"auth-divider-line\"></div><span class=\"auth-divider-text\">OR</span><div class=\"auth-divider-line\"></div></div>\r\n          <button class=\"auth-main-btn secondary\" onclick=\"showAuthView('signup')\">Create an account</button>\r\n          <button class=\"auth-main-btn secondary\" onclick=\"enterGuestMode()\">\r\n            Try for Free\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"14\" height=\"14\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"auth-panel-view\" id=\"authLoginView\">\r\n        <div class=\"auth-panel-title\">Log in</div>\r\n        <div class=\"auth-panel-sub\">Enter your credentials to continue.</div>\r\n        <div class=\"auth-form\" id=\"loginForm\">\r\n          <div class=\"auth-field\">\r\n            <div class=\"auth-field-label\">Email address</div>\r\n            <input type=\"email\" class=\"auth-input\" id=\"loginEmail\" name=\"hether_login_local_part\" placeholder=\"you@example.com\" autocomplete=\"new-password\" autocorrect=\"off\" autocapitalize=\"off\" spellcheck=\"false\" onkeydown=\"authKeyHandler(event,'login')\">\r\n          </div>\r\n          <div class=\"auth-field\">\r\n            <div class=\"auth-field-label\">Password</div>\r\n            <input type=\"password\" class=\"auth-input\" id=\"loginPassword\" name=\"hether_login_secret\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" autocomplete=\"new-password\" onkeydown=\"authKeyHandler(event,'login')\">\r\n          </div>\r\n          <div class=\"auth-form-error\" id=\"loginError\">Invalid email or password. Please try again.</div>\r\n          <button class=\"auth-submit-btn\" onclick=\"handleLoginSubmit()\">Log in</button>\r\n        </div>\r\n        <div class=\"auth-switch-link\">Don't have an account? <button onclick=\"showAuthView('signup')\">Sign up</button></div>\r\n        <div class=\"auth-back-link\"><button onclick=\"showAuthView('landing')\">\u2190 Back</button></div>\r\n      </div>\r\n\r\n      <div class=\"auth-panel-view\" id=\"authSignupView\">\r\n        <div class=\"auth-panel-title\">Create account</div>\r\n        <div class=\"auth-panel-sub\">Join Hether \u2014 it's free.</div>\r\n        <div class=\"auth-form\" id=\"signupForm\">\r\n          <div class=\"auth-field\">\r\n            <div class=\"auth-field-label\">Username</div>\r\n            <input type=\"text\" class=\"auth-input\" id=\"signupUsername\" name=\"hether_signup_handle\" placeholder=\"yourname\" autocomplete=\"off\" autocorrect=\"off\" autocapitalize=\"off\" spellcheck=\"false\" onkeydown=\"authKeyHandler(event,'signup')\">\r\n          </div>\r\n          <div class=\"auth-field\">\r\n            <div class=\"auth-field-label\">Email address</div>\r\n            <input type=\"email\" class=\"auth-input\" id=\"signupEmail\" name=\"hether_signup_local_part\" placeholder=\"you@example.com\" autocomplete=\"new-password\" autocorrect=\"off\" autocapitalize=\"off\" spellcheck=\"false\" onkeydown=\"authKeyHandler(event,'signup')\">\r\n          </div>\r\n          <div class=\"auth-field\">\r\n            <div class=\"auth-field-label\">Password</div>\r\n            <input type=\"password\" class=\"auth-input\" id=\"signupPassword\" name=\"hether_signup_secret\" placeholder=\"Min 8 characters\" autocomplete=\"new-password\" onkeydown=\"authKeyHandler(event,'signup')\">\r\n          </div>\r\n          <div class=\"auth-form-error\" id=\"signupError\">Please fill in all fields correctly.</div>\r\n          <button class=\"auth-submit-btn\" onclick=\"handleSignupSubmit()\">Create account</button>\r\n        </div>\r\n        <div class=\"auth-switch-link\">Already have an account? <button onclick=\"showAuthView('login')\">Log in</button></div>\r\n        <div class=\"auth-back-link\"><button onclick=\"showAuthView('landing')\">\u2190 Back</button></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"auth-footer\">By continuing, you agree to our Terms of Service &amp; Privacy Policy.</div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"mobile-overlay\" id=\"mobileOverlay\" onclick=\"hideSidebar()\"></div>\r\n<div class=\"sidebar-trigger\" id=\"sidebarTrigger\"></div>\r\n\r\n<!-- MAIN APP -->\r\n<div id=\"mainApp\" style=\"display: none; width: 100%; height: 100%;\">\r\n\r\n<aside class=\"sidebar\" id=\"sidebar\">\r\n  <div class=\"logo\">\r\n    <div class=\"logo-icon\">\r\n      <img src=\"data:image/png;base64,\" alt=\"Hether logo\" style=\"width:100%;height:100%;object-fit:contain;\">\r\n    </div>\r\n    <span class=\"logo-text\">Hether</span>\r\n  </div>\r\n\r\n  <div class=\"sidebar-nav-center\">\r\n  <button class=\"nav-btn\" id=\"navRelay\" onclick=\"showView('relay')\" data-tip=\"Assist\">\r\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-brain-icon lucide-brain\"><path d=\"M12 18V5\"/><path d=\"M15 13a4.17 4.17 0 0 1-3-4 4.17 4.17 0 0 1-3 4\"/><path d=\"M17.598 6.5A3 3 0 1 0 12 5a3 3 0 1 0-5.598 1.5\"/><path d=\"M17.997 5.125a4 4 0 0 1 2.526 5.77\"/><path d=\"M18 18a4 4 0 0 0 2-7.464\"/><path d=\"M19.967 17.483A4 4 0 1 1 12 18a4 4 0 1 1-7.967-.517\"/><path d=\"M6 18a4 4 0 0 1-2-7.464\"/><path d=\"M6.003 5.125a4 4 0 0 0-2.526 5.77\"/></svg>\r\n    <span class=\"nav-btn-label\">Assist</span>\r\n  </button>\r\n\r\n  <button class=\"nav-btn\" id=\"navAloft\" onclick=\"showView('aloft')\" data-tip=\"Aloft\">\r\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17.5 12a1 1 0 1 1 0 9H9.006a7 7 0 1 1 6.702-9z\"/><path d=\"M21.832 9A3 3 0 0 0 19 7h-2.207a5.5 5.5 0 0 0-10.72.61\"/></svg>\r\n    <span class=\"nav-btn-label\">Aloft</span>\r\n  </button>\r\n\r\n  <button class=\"nav-btn active\" id=\"navExplore\" onclick=\"showView('explore')\" data-tip=\"Explore\">\r\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-library-big-icon lucide-library-big\"><rect width=\"8\" height=\"18\" x=\"3\" y=\"3\" rx=\"1\"/><path d=\"M7 3v18\"/><path d=\"M20.4 18.9c.2.5-.1 1.1-.6 1.3l-1.9.7c-.5.2-1.1-.1-1.3-.6L11.1 5.1c-.2-.5-.1-1.1.6-1.3l1.9-.7c.5-.2 1.1-.1 1.3.6Z\"/></svg>\r\n    <span class=\"nav-btn-label\">Explore</span>\r\n  </button>\r\n\r\n  <button class=\"nav-btn\" id=\"navFavourites\" onclick=\"showView('favourites')\" data-tip=\"Search\">\r\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-search-icon lucide-search\"><path d=\"m21 21-4.34-4.34\"/><circle cx=\"11\" cy=\"11\" r=\"8\"/></svg>\r\n    <span class=\"nav-btn-label\">Search</span>\r\n  </button>\r\n\r\n  <button class=\"nav-btn\" id=\"navNotes\" onclick=\"showView('notes')\" data-tip=\"Spotlight\">\r\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-audio-waveform-icon lucide-audio-waveform\"><path d=\"M2 13a2 2 0 0 0 2-2V7a2 2 0 0 1 4 0v13a2 2 0 0 0 4 0V4a2 2 0 0 1 4 0v13a2 2 0 0 0 4 0v-4a2 2 0 0 1 2-2\"/></svg>\r\n    <span class=\"nav-btn-label\">Spotlight</span>\r\n  </button>\r\n\r\n  <button class=\"nav-btn\" id=\"navLibrary\" onclick=\"showView('library')\" data-tip=\"Library\">\r\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-badge-plus-icon lucide-badge-plus\"><path d=\"M3.85 8.62a4 4 0 0 1 4.78-4.77 4 4 0 0 1 6.74 0 4 4 0 0 1 4.78 4.78 4 4 0 0 1 0 6.74 4 4 0 0 1-4.77 4.78 4 4 0 0 1-6.75 0 4 4 0 0 1-4.78-4.77 4 4 0 0 1 0-6.76Z\"/><line x1=\"12\" x2=\"12\" y1=\"8\" y2=\"16\"/><line x1=\"8\" x2=\"16\" y1=\"12\" y2=\"12\"/></svg>\r\n    <span class=\"nav-btn-label\">Library</span>\r\n  </button>\r\n\r\n  <button class=\"nav-btn\" id=\"navSettings\" onclick=\"showView('settings')\" data-tip=\"Settings\">\r\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"/></svg>\r\n    <span class=\"nav-btn-label\">Settings</span>\r\n  </button>\r\n\r\n  <button class=\"nav-btn\" id=\"navDownload\" onclick=\"handleDownloadClick()\" data-tip=\"Download\">\r\n    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\r\n    <span class=\"nav-btn-label\">Download</span>\r\n  </button>\r\n\r\n  </div>\r\n\r\n  <div class=\"sidebar-spacer\"></div>\r\n\r\n  <button class=\"profile-btn\" id=\"profileBtn\" onclick=\"showView('profile')\" data-tip=\"Profile\">\r\n    <div class=\"profile-avatar default-avatar\" id=\"sidebarProfileAvatar\">\r\n      <!-- filled by JS -->\r\n    </div>\r\n    <span class=\"profile-display-name\" id=\"sidebarProfileName\">User</span>\r\n  </button>\r\n  <button class=\"profile-btn\" id=\"guestSignupBtn\" onclick=\"goToSignupFromGuest()\" data-tip=\"Sign up\" style=\"display:none;\">\r\n    <div class=\"profile-avatar default-avatar\" id=\"guestSignupAvatar\">\r\n      <!-- filled by JS with the blank silhouette -->\r\n    </div>\r\n    <span class=\"profile-display-name\">Guest</span>\r\n  </button>\r\n</aside>\r\n\r\n<!-- PROFILE DROPDOWN -->\r\n<div class=\"profile-dropdown\" id=\"profileDropdown\">\r\n  <div class=\"pd-header\">\r\n    <div class=\"pd-avatar-large default-avatar\" id=\"pdAvatarLarge\" onclick=\"openProfileEdit()\">\r\n      <!-- filled by JS -->\r\n      <div class=\"pd-avatar-overlay\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\"><path d=\"M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z\"/><circle cx=\"12\" cy=\"13\" r=\"4\"/></svg>\r\n      </div>\r\n    </div>\r\n    <div class=\"pd-user-info\">\r\n      <div class=\"pd-name\" id=\"pdDisplayName\">User</div>\r\n      <div class=\"pd-email\" id=\"pdEmail\">user@example.com</div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"pd-items\">\r\n    <button class=\"pd-item\" onclick=\"openProfileEdit()\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>\r\n      Edit Profile\r\n    </button>\r\n    <button class=\"pd-item\" onclick=\"toggleAccountSwitcher()\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\r\n      Switch Account\r\n      <svg id=\"switchArrow\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" style=\"margin-left:auto;transition:transform 0.2s;\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n    </button>\r\n    <div class=\"pd-accounts\" id=\"pdAccounts\">\r\n      <button class=\"pd-account-item active-acc\" onclick=\"switchAccount(0)\">\r\n        <div class=\"pd-acc-dot\" style=\"background:linear-gradient(135deg,#5b6af0,#a855f7);\">U</div>\r\n        <span id=\"acc0Name\">User (current)</span>\r\n      </button>\r\n      <button class=\"pd-add-acc\" onclick=\"addAccount()\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"14\" height=\"14\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\r\n        Add account\r\n      </button>\r\n    </div>\r\n    <div class=\"pd-divider\"></div>\r\n    <button class=\"pd-item danger\" onclick=\"logOut()\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg>\r\n      Log out\r\n    </button>\r\n  </div>\r\n</div>\r\n\r\n<main class=\"main sidebar-mini\" id=\"mainArea\">\r\n\r\n  <div class=\"relay-view welcome-mode\" id=\"relayView\">\r\n    <div class=\"messages\" id=\"messages\"></div>\r\n    <div class=\"input-area\">\r\n      <div class=\"welcome\" id=\"welcomeScreen\">\r\n        <div class=\"welcome-hello\" id=\"welcomeHello\">Hello, User</div>\r\n      </div>\r\n      <div class=\"media-staging-wrap\" id=\"mediaStagingWrap\">\r\n        <div class=\"media-staging-inner\">\r\n          <div class=\"media-staging-thumb\" id=\"mediaStagingThumb\"></div>\r\n          <div class=\"media-staging-right\">\r\n            <textarea class=\"media-staging-caption\" id=\"mediaStagingCaption\" placeholder=\"Add a caption\u2026\" rows=\"2\"></textarea>\r\n            <button class=\"media-staging-send\" onclick=\"sendStagedMedia()\">Send</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"input-wrap\">\r\n        <button class=\"emoji-btn\" id=\"emojiBtn\" onclick=\"toggleEmojiPicker('relay')\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" x2=\"9.01\" y1=\"9\" y2=\"9\"/><line x1=\"15\" x2=\"15.01\" y1=\"9\" y2=\"9\"/></svg>\r\n        </button>\r\n        <textarea id=\"userInput\" rows=\"1\" placeholder=\"Message\" oninput=\"autoResize(this); toggleMediaButton()\" onkeydown=\"handleKey(event)\" onpaste=\"handleRelayPaste(event)\"></textarea>\r\n        <button class=\"send-btn\" id=\"sendBtn\" onclick=\"sendMessage()\" disabled>\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"5\"/><polyline points=\"5 12 12 5 19 12\"/></svg>\r\n        </button>\r\n        <input type=\"file\" id=\"aiMediaUpload\" accept=\"image/*,video/*\" style=\"display:none\" onchange=\"stageAIMedia(event)\">\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- NOTES VIEW -->\r\n  <!-- ALOFT GAME VIEW -->\r\n  <div id=\"aloftView\" style=\"display:none;flex:1;position:relative;overflow:hidden;background:#000;\">\r\n    <canvas id=\"aloftCanvas\" style=\"image-rendering:pixelated;image-rendering:crisp-edges;display:block;position:absolute;top:0;left:0;\"></canvas>\r\n    <div id=\"aloftOverlay\" style=\"position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;\">\r\n      <div id=\"aloftStartScreen\" style=\"display:flex;flex-direction:column;align-items:center;gap:18px;pointer-events:all;\">\r\n        <div style=\"font-family:'DM Mono',monospace;font-size:36px;font-weight:700;color:#fff;letter-spacing:6px;\">ALOFT</div>\r\n        <div style=\"font-size:12px;color:rgba(255,255,255,0.5);font-family:'DM Mono',monospace;\">Jump from platform to platform</div>\r\n        <div style=\"font-size:11px;color:rgba(255,255,255,0.4);font-family:'DM Mono',monospace;\">A/D or \u2190 \u2192 to move &nbsp;|&nbsp; SPACE / \u2191 / W to jump</div>\r\n        <div id=\"aloftBestDisplay\" style=\"font-size:12px;color:rgba(255,255,255,0.6);font-family:'DM Mono',monospace;\"></div>\r\n        <button onclick=\"aloftStart()\" style=\"padding:11px 32px;background:#fff;color:#000;border:none;border-radius:2px;font-family:'DM Mono',monospace;font-size:13px;cursor:pointer;letter-spacing:2px;font-weight:700;\">START</button>\r\n      </div>\r\n      <div id=\"aloftGameOverScreen\" style=\"display:none;flex-direction:column;align-items:center;gap:14px;pointer-events:all;\">\r\n        <div style=\"font-family:'DM Mono',monospace;font-size:24px;font-weight:700;color:#fff;letter-spacing:4px;\">GAME OVER</div>\r\n        <div id=\"aloftFinalScore\" style=\"font-size:13px;color:rgba(255,255,255,0.6);font-family:'DM Mono',monospace;\"></div>\r\n        <div id=\"aloftNewBest\" style=\"font-size:12px;color:#fff;font-family:'DM Mono',monospace;display:none;letter-spacing:2px;\">* NEW BEST *</div>\r\n        <button onclick=\"aloftStart()\" style=\"padding:11px 32px;background:#fff;color:#000;border:none;border-radius:2px;font-family:'DM Mono',monospace;font-size:13px;cursor:pointer;letter-spacing:2px;font-weight:700;\">RETRY</button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ALOFT TOUCH CONTROLS: left half = move arrows, right half = tap to jump/double-jump -->\r\n    <div id=\"aloftTouchControls\" style=\"position:absolute;inset:0;display:none;pointer-events:none;\">\r\n      <div id=\"aloftMoveZone\" style=\"position:absolute;left:0;top:0;width:50%;height:100%;display:flex;align-items:flex-end;justify-content:flex-start;gap:14px;padding:0 0 22px 22px;touch-action:none;pointer-events:auto;\">\r\n        <button type=\"button\" id=\"aloftBtnLeft\" aria-label=\"Move left\" style=\"width:58px;height:58px;border-radius:3px;background:rgba(255,255,255,0.12);border:1px solid rgba(255,255,255,0.3);color:#fff;display:flex;align-items:center;justify-content:center;-webkit-user-select:none;user-select:none;touch-action:none;image-rendering:pixelated;\">\r\n          <svg width=\"26\" height=\"26\" viewBox=\"0 0 40 40\" style=\"image-rendering:pixelated;transform:scaleX(-1);pointer-events:none;\"><rect x=\"8\" y=\"0\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"16\" y=\"8\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"24\" y=\"16\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"16\" y=\"24\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"8\" y=\"32\" width=\"8\" height=\"8\" fill=\"#fff\"/></svg>\r\n        </button>\r\n        <button type=\"button\" id=\"aloftBtnRight\" aria-label=\"Move right\" style=\"width:58px;height:58px;border-radius:3px;background:rgba(255,255,255,0.12);border:1px solid rgba(255,255,255,0.3);color:#fff;display:flex;align-items:center;justify-content:center;-webkit-user-select:none;user-select:none;touch-action:none;image-rendering:pixelated;\">\r\n          <svg width=\"26\" height=\"26\" viewBox=\"0 0 40 40\" style=\"image-rendering:pixelated;pointer-events:none;\"><rect x=\"8\" y=\"0\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"16\" y=\"8\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"24\" y=\"16\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"16\" y=\"24\" width=\"8\" height=\"8\" fill=\"#fff\"/><rect x=\"8\" y=\"32\" width=\"8\" height=\"8\" fill=\"#fff\"/></svg>\r\n        </button>\r\n      </div>\r\n      <div id=\"aloftJumpZone\" style=\"position:absolute;right:0;top:0;width:50%;height:100%;touch-action:none;pointer-events:auto;\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"notes-view spotlight-view\" id=\"notesView\">\r\n    <div class=\"spotlight-layout\" id=\"spotlightLayout\">\r\n      <div class=\"spotlight-left\">\r\n        <div class=\"spotlight-card-wrap\" id=\"spotlightCardWrap\"></div>\r\n        <div class=\"spotlight-song-title\" id=\"spotlightSongTitle\"></div>\r\n        <div class=\"spotlight-timer-wrap\" id=\"spotlightTimerWrap\">\r\n          <div class=\"spotlight-timer\">\r\n            <div class=\"spotlight-timer-bar-wrap\">\r\n              <div class=\"spotlight-timer-bar-fill\" id=\"spotlightTimerBarFill\"></div>\r\n            </div>\r\n            <div class=\"spotlight-timer-main\">\r\n              <div class=\"spotlight-timer-time\">\r\n                <span id=\"spotlightTimerMins\">00</span><span class=\"spotlight-timer-divider\"></span><span id=\"spotlightTimerSecs\">00</span>\r\n              </div>\r\n            </div>\r\n            <div class=\"spotlight-timer-caption\">Sit back while we handle your music</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"spotlight-actions\" id=\"spotlightActions\">\r\n          <button type=\"button\" class=\"spotlight-start-btn\" id=\"spotlightStartBtn\" onclick=\"startSpotlightFocus()\">Start Focus</button>\r\n          <button type=\"button\" class=\"spotlight-start-btn spotlight-pause-btn\" id=\"spotlightPauseBtn\" onclick=\"toggleSpotlightPause()\" style=\"display:none;\">Pause</button>\r\n        </div>\r\n      </div>\r\n      <div class=\"spotlight-playlist\" id=\"spotlightPlaylist\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Focus duration picker -->\r\n  <div class=\"overlay\" id=\"focusDurationOverlay\">\r\n    <div class=\"popup focus-popup\">\r\n      <h3>Start a focus session</h3>\r\n      <p>Choose how long you want to focus for.</p>\r\n      <div class=\"focus-duration-grid\" id=\"focusDurationGrid\">\r\n        <button type=\"button\" class=\"focus-duration-opt\" onclick=\"selectFocusDuration(5)\">5 min</button>\r\n        <button type=\"button\" class=\"focus-duration-opt\" onclick=\"selectFocusDuration(15)\">15 min</button>\r\n        <button type=\"button\" class=\"focus-duration-opt\" onclick=\"selectFocusDuration(25)\">25 min</button>\r\n        <button type=\"button\" class=\"focus-duration-opt\" onclick=\"selectFocusDuration(40)\">40 min</button>\r\n        <button type=\"button\" class=\"focus-duration-opt focus-custom-opt\" id=\"focusCustomOptBtn\" onclick=\"showFocusCustomInput()\">Custom</button>\r\n        <button type=\"button\" class=\"focus-duration-start-btn\" id=\"focusCustomStartBtn\" onclick=\"confirmFocusCustom()\">Start</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXPLORE VIEW -->\r\n  <div class=\"explore-view\" id=\"exploreView\" style=\"display:none;flex:1;overflow:hidden;\">\r\n    <div class=\"explore-body\" id=\"exploreBody\">\r\n      <div class=\"explore-top-row\" id=\"exploreTopRow\"></div>\r\n      <div class=\"explore-section-title\">Based on your interest</div>\r\n      <div class=\"explore-interest-list lib-list\" id=\"exploreInterestList\"></div>\r\n      <div class=\"explore-section-title\">Explore more</div>\r\n      <div class=\"explore-more-grid\" id=\"exploreMoreGrid\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- FAVOURITES VIEW (repurposed as Search) -->\r\n  <div class=\"favourites-view search-page\" id=\"favouritesView\" style=\"display:none;flex:1;overflow:hidden;\">\r\n    <div class=\"search-page-inner\">\r\n      <div class=\"lib-banner\" id=\"searchBanner\">\r\n        <div class=\"lib-banner-search\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.3-4.3\"/></svg>\r\n          <input type=\"text\" id=\"searchPageInput\" placeholder=\"Search\" autocomplete=\"off\" oninput=\"handleSearchPageInput()\">\r\n        </div>\r\n        <div class=\"lib-banner-title\"><span class=\"lib-banner-title-line1\">Find Your</span><span class=\"lib-banner-title-line2\">Next Track</span></div>\r\n      </div>\r\n      <div class=\"search-page-results\" id=\"searchPageResults\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- PROFILE VIEW -->\r\n  <div class=\"profile-view\" id=\"profileView\" style=\"display:none;flex:1;overflow:hidden;\">\r\n    <div class=\"profile-page-body\" id=\"profilePageBody\">\r\n      <div class=\"profile-banner\" id=\"profileBanner\">\r\n        <div class=\"profile-banner-content\">\r\n          <div class=\"profile-banner-avatar-wrap\" onclick=\"openAvatarPicker()\" title=\"Change profile picture\">\r\n            <div class=\"profile-banner-avatar default-avatar\" id=\"profileBannerAvatar\"></div>\r\n            <div class=\"profile-banner-avatar-overlay\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.3 20H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.98a2 2 0 0 1 1.69.9l.66 1.2A2 2 0 0 0 12 6h8a2 2 0 0 1 2 2v3.3\"/><path d=\"m14.305 19.53.923-.382\"/><path d=\"m15.228 16.852-.923-.383\"/><path d=\"m16.852 15.228-.383-.923\"/><path d=\"m16.852 20.772-.383.924\"/><path d=\"m19.148 15.228.383-.923\"/><path d=\"m19.53 21.696-.382-.924\"/><path d=\"m20.772 16.852.924-.383\"/><path d=\"m20.772 19.148.924.383\"/><circle cx=\"18\" cy=\"18\" r=\"3\"/></svg>\r\n            </div>\r\n          </div>\r\n          <div class=\"profile-banner-text\">\r\n            <div class=\"profile-banner-label\">Profile</div>\r\n            <div class=\"profile-banner-name\" id=\"profileBannerName\" onclick=\"openProfileEdit()\" title=\"Edit display name\">User</div>\r\n            <div class=\"profile-banner-username\" id=\"profileBannerUsername\">username</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"profile-songs-section\" id=\"profileSongsSection\" style=\"display:none;\">\r\n        <div class=\"profile-songs-title\">Most played</div>\r\n        <div class=\"profile-songs-row\" id=\"profileSongsRow\"></div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Hidden input used by the profile banner avatar to open a picker directly -->\r\n  <input type=\"file\" id=\"bannerAvatarUpload\" accept=\"image/*\" style=\"display:none\" onchange=\"openCropModal(event)\">\r\n\r\n  <!-- LIBRARY VIEW -->\r\n  <div class=\"library-view\" id=\"libraryView\">\r\n    <div class=\"lib-banner\" id=\"libBanner\">\r\n      <div class=\"lib-banner-search\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.3-4.3\"/></svg>\r\n        <input type=\"text\" id=\"libBannerSearchInput\" placeholder=\"Search\" autocomplete=\"off\" oninput=\"handleLibBannerSearchInput()\">\r\n      </div>\r\n      <div class=\"lib-banner-title\" id=\"libBannerTitle\"><span class=\"lib-banner-title-line1\">Tune Into</span><span class=\"lib-banner-title-line2\">Everything</span></div>\r\n    </div>\r\n    <div class=\"lib-create-row\" id=\"libCreateRow\">\r\n      <button class=\"lib-upload-btn\" onclick=\"openLibUpload()\">Create</button>\r\n    </div>\r\n    <div class=\"lib-body\">\r\n      <div class=\"lib-grid\" id=\"libGrid\"></div>\r\n      <div class=\"lib-list\" id=\"libList\"></div>\r\n    </div>\r\n    <audio id=\"libAudio\" style=\"display:none;\"></audio>\r\n\r\n    <!-- LIBRARY UPLOAD MODAL (confined to the middle/body column only) -->\r\n    <div class=\"lib-modal-overlay\" id=\"libModalOverlay\" onclick=\"if(event.target===this) closeLibUpload()\">\r\n      <div class=\"lib-modal\">\r\n        <div class=\"lib-thumb-wrap\">\r\n          <div class=\"lib-thumb-drop\" id=\"libThumbDrop\" onclick=\"handleLibThumbDropClick(event)\">\r\n            <div class=\"lib-thumb-label-row\">\r\n              <div class=\"lib-thumb-np-thumb\" id=\"libThumbNpThumb\" title=\"Now playing thumbnail\">\r\n                <img id=\"libThumbNpThumbImg\" alt=\"\">\r\n              </div>\r\n              <span id=\"libThumbPlaceholder\">Thumbnail</span>\r\n            </div>\r\n            <img id=\"libThumbPreview\" draggable=\"false\" style=\"display:none;\"\r\n                 onmousedown=\"libThumbPointerDown(event)\" ontouchstart=\"libThumbPointerDown(event)\">\r\n            <div class=\"lib-thumb-reposition-hint\" id=\"libThumbRepositionHint\">Drag to reposition</div>\r\n          </div>\r\n        </div>\r\n        <input type=\"file\" id=\"libThumbInput\" accept=\"image/*\" style=\"display:none\" onchange=\"handleLibThumbSelect(event)\">\r\n        <div class=\"lib-modal-fields\">\r\n        <div class=\"lib-music-field\" id=\"libMusicField\">\r\n          <div class=\"lib-icon-group\">\r\n            <button type=\"button\" class=\"lib-icon-btn\" id=\"libArtistToggleBtn\" onclick=\"toggleLibArtistBox()\" title=\"Add artist\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><line x1=\"19\" x2=\"19\" y1=\"8\" y2=\"14\"/><line x1=\"22\" x2=\"16\" y1=\"11\" y2=\"11\"/></svg>\r\n            </button>\r\n            <button type=\"button\" class=\"lib-icon-btn\" id=\"libNowPlayingBtn\" onclick=\"openLibCropModal()\" title=\"Add now playing thumbnail\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-turntable-icon lucide-turntable\"><path d=\"M10 12.01h.01\"/><path d=\"M18 8v4a8 8 0 0 1-1.07 4\"/><circle cx=\"10\" cy=\"12\" r=\"4\"/><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/></svg>\r\n            </button>\r\n          </div>\r\n          <button type=\"button\" class=\"lib-file-btn\" id=\"libMusicBtn\" title=\"Music file (required)\" onclick=\"document.getElementById('libMusicInput').click()\">Add audio</button>\r\n          <input type=\"file\" id=\"libMusicInput\" accept=\"audio/*\" style=\"display:none\" onchange=\"handleLibMusicSelect(event)\">\r\n        </div>\r\n        <span id=\"libMusicLabel\" class=\"lib-music-caption\"></span>\r\n        <div class=\"lib-artist-box\" id=\"libArtistBox\">\r\n          <span class=\"lib-artist-box-label\">Add artist</span>\r\n          <input type=\"text\" id=\"libArtistInput\">\r\n        </div>\r\n        <button type=\"button\" class=\"lib-file-btn lib-artist-save-btn\" id=\"libArtistSaveBtn\" onclick=\"toggleLibArtistBox()\">Save</button>\r\n        <div class=\"lib-divider\"></div>\r\n        <div class=\"lib-title-box\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 9.17a3 3 0 1 0 0 5.66\"/><path d=\"M17 9.17a3 3 0 1 0 0 5.66\"/><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/></svg>\r\n          <input type=\"text\" id=\"libTitleInput\" placeholder=\"Enter title (max 3 words)\" onkeydown=\"handleLibTitleEnter(event)\" oninput=\"enforceLibTitleWordLimit(event)\">\r\n        </div>\r\n        <div class=\"lib-modal-error\" id=\"libModalError\"></div>\r\n        <div class=\"lib-modal-actions\">\r\n          <button class=\"lib-btn-cancel\" onclick=\"closeLibUpload()\">Back</button>\r\n          <button class=\"lib-btn-submit\" id=\"libSubmitBtn\" onclick=\"submitLibUpload()\">Upload</button>\r\n        </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- NOW PLAYING THUMBNAIL CROP MODAL -->\r\n    <div class=\"lib-crop-modal-overlay\" id=\"libCropModalOverlay\" onclick=\"if(event.target===this) closeLibCropModal()\">\r\n      <div class=\"lib-crop-modal\">\r\n        <h3>Now playing thumbnail</h3>\r\n        <p class=\"lib-crop-modal-desc\">This image shows up in the Now Playing panel while this track is playing. Pick a photo from your files, then drag and zoom to fit it into the frame.</p>\r\n        <div class=\"lib-crop-picker\" id=\"libCropPicker\">\r\n          <button type=\"button\" class=\"lib-file-btn\" onclick=\"document.getElementById('libCropFileInput').click()\">Choose from files</button>\r\n          <input type=\"file\" id=\"libCropFileInput\" accept=\"image/*\" style=\"display:none\" onchange=\"handleLibCropFileSelect(event)\">\r\n        </div>\r\n        <div class=\"lib-crop-stage\" id=\"libCropStage\" style=\"display:none;\">\r\n          <div class=\"lib-crop-frame\" id=\"libCropFrame\"\r\n               onpointerdown=\"libCropPointerDown(event)\" onpointermove=\"libCropPointerMove(event)\"\r\n               onpointerup=\"libCropPointerUp(event)\" onpointerleave=\"libCropPointerUp(event)\" onpointercancel=\"libCropPointerUp(event)\">\r\n            <img id=\"libCropImage\" draggable=\"false\">\r\n          </div>\r\n          <div class=\"lib-crop-hint\">Drag to reposition</div>\r\n          <div class=\"lib-crop-actions\">\r\n            <button type=\"button\" class=\"lib-btn-cancel\" onclick=\"closeLibCropModal()\">Cancel</button>\r\n            <button type=\"button\" class=\"lib-btn-submit\" onclick=\"confirmLibCrop()\">Use photo</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- NOW PLAYING PANEL (shared, fixed, shown on library / explore / favourites) -->\r\n  <div class=\"now-playing-panel\" id=\"nowPlayingPanel\">\r\n    <div class=\"np-empty\" id=\"npEmpty\">Nothing's playing right now.<br>Pick a song from Library to start listening.</div>\r\n    <div class=\"np-content\" id=\"npContent\">\r\n      <div class=\"np-thumb-wrap\">\r\n        <img class=\"np-thumb\" id=\"npThumb\" src=\"\" alt=\"\">\r\n        <div class=\"np-thumb-fade\"></div>\r\n        <div class=\"np-thumb-title\" id=\"npTitle\">\u2014</div>\r\n        <div class=\"np-song-artist\" id=\"npArtist\">\u2014</div>\r\n      </div>\r\n      <div class=\"np-queue-card\" id=\"npCreditsCard\" style=\"display:none;\">\r\n        <div class=\"np-queue-heading\">Credits</div>\r\n        <div class=\"np-credits-author\" id=\"npCreditsAuthor\">\u2014</div>\r\n        <div class=\"np-credits-role\">Main Artist</div>\r\n      </div>\r\n      <div class=\"np-queue-card\" id=\"npQueueCard\" style=\"display:none;\">\r\n        <div class=\"np-queue-heading\">Next in queue</div>\r\n        <div class=\"np-queue-song\">\r\n          <div class=\"np-queue-thumb-wrap\">\r\n            <img class=\"np-queue-thumb\" id=\"npQueueThumb\" src=\"\" alt=\"\">\r\n            <button type=\"button\" class=\"np-queue-play-btn\" id=\"npQueuePlayBtn\" onclick=\"event.stopPropagation(); playQueuedNextSong();\" title=\"Play now\">\r\n              <svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M8 5v14l11-7z\"/></svg>\r\n            </button>\r\n          </div>\r\n          <div class=\"np-queue-text\">\r\n            <div class=\"np-queue-title\" id=\"npQueueTitle\">\u2014</div>\r\n            <div class=\"np-queue-author\" id=\"npQueueAuthor\">Anonymous</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"np-queue-duration\" id=\"npQueueDuration\">--:--</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- SPOTIFY-STYLE PERSISTENT BOTTOM PLAYER BAR -->\r\n  <div class=\"sb-device-menu\" id=\"sbDeviceMenu\" style=\"display:none;\"></div>\r\n\r\n  <div class=\"spotify-bar\" id=\"spotifyBar\">\r\n    <div class=\"sb-now-playing\">\r\n      <img class=\"sb-thumb\" id=\"sbThumb\" src=\"\" alt=\"\">\r\n      <div class=\"sb-meta\">\r\n        <div class=\"sb-title\" id=\"sbTitle\">\u2014</div>\r\n        <div class=\"sb-artist\" id=\"sbArtist\">\u2014</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"sb-center\">\r\n      <div class=\"sb-controls\">\r\n        <button class=\"sb-btn sb-mode\" id=\"sbPlayMode\" onclick=\"toggleLibPlayMode()\" title=\"Play mode: Sequential\">\r\n          <span id=\"sbPlayModeIcon\"></span>\r\n        </button>\r\n        <button class=\"sb-btn sb-skip\" id=\"sbPrev\" onclick=\"playPrevLibSong()\" title=\"Previous\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"1\" stroke-linejoin=\"round\"><path d=\"M6 6h2v12H6zm3.5 6 8.5 6V6z\"/></svg>\r\n        </button>\r\n        <button class=\"sb-btn sb-toggle\" id=\"sbToggle\" onclick=\"toggleLibPlayback()\">\r\n          <svg id=\"sbIcon\" viewBox=\"0 0 24 24\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"1\" stroke-linejoin=\"round\"><path d=\"M8 5v14l11-7z\"/></svg>\r\n        </button>\r\n        <button class=\"sb-btn sb-skip\" id=\"sbNext\" onclick=\"playNextLibSong()\" title=\"Next\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"1\" stroke-linejoin=\"round\"><path d=\"M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z\"/></svg>\r\n        </button>\r\n        <button class=\"sb-btn sb-repeat\" id=\"sbRepeat\" onclick=\"toggleLibRepeatMode()\" title=\"Repeat: Off\">\r\n          <span id=\"sbRepeatIcon\"></span>\r\n        </button>\r\n      </div>\r\n      <div class=\"sb-progress\">\r\n        <span class=\"sb-time\" id=\"npCur\">0:00</span>\r\n        <input type=\"range\" class=\"sb-range sb-seek\" id=\"npSeek\" min=\"0\" max=\"100\" value=\"0\" step=\"0.1\" oninput=\"seekLibPlayback(this.value)\">\r\n        <span class=\"sb-time\" id=\"npDur\">0:00</span>\r\n      </div>\r\n    </div>\r\n    <div class=\"sb-right\">\r\n      <button class=\"sb-icon-btn\" id=\"sbDeviceBtn\" onclick=\"connectToDevice()\" title=\"Connect to a device\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-headphones-icon lucide-headphones\"><path d=\"M3 14h3a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-7a9 9 0 0 1 18 0v7a2 2 0 0 1-2 2h-1a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2h3\"/></svg>\r\n      </button>\r\n      <div class=\"sb-volume\">\r\n        <svg class=\"sb-vol-icon\" id=\"sbVolIcon\" xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M11 4.702a.705.705 0 0 0-1.203-.498L6.413 7.587A1.4 1.4 0 0 1 5.416 8H3a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2.416a1.4 1.4 0 0 1 .997.413l3.383 3.384A.705.705 0 0 0 11 19.298z\"/><path d=\"M16 9a5 5 0 0 1 0 6\"/><path d=\"M19.364 18.364a9 9 0 0 0 0-12.728\"/></svg>\r\n        <input type=\"range\" class=\"sb-range sb-vol-seek\" id=\"sbVolume\" min=\"0\" max=\"100\" value=\"100\" oninput=\"setLibVolume(this.value)\">\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"history-view\" id=\"historyView\">\r\n    <div class=\"history-header\">\r\n      <button class=\"hamburger\" style=\"display:flex;\" onclick=\"toggleSidebarMobile()\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" width=\"18\" height=\"18\"><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"/><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"/><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"/></svg>\r\n      </button>\r\n      <h2>Relay History</h2>\r\n      <button class=\"clear-output-btn\" onclick=\"clearAllHistory()\" style=\"margin-left:auto;\">Clear all</button>\r\n    </div>\r\n    <div class=\"history-list\" id=\"historyList\"></div>\r\n  </div>\r\n\r\n  <!-- SETTINGS VIEW -->\r\n  <div class=\"settings-view\" id=\"settingsView\">\r\n    <div class=\"settings-body\">\r\n\r\n      <!-- Left nav -->\r\n      <div class=\"settings-nav-wrap\" id=\"settingsNavWrap\"><nav class=\"settings-nav\" id=\"settingsNav\">\r\n        <div class=\"settings-nav-title\">Settings</div>\r\n\r\n        <div class=\"settings-search-wrap\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n          <input class=\"settings-search\" type=\"text\" placeholder=\"Search settings\u2026\" oninput=\"filterSettingsNav(this.value)\" autocomplete=\"off\" spellcheck=\"false\">\r\n        </div>\r\n\r\n        <div class=\"settings-nav-group-label\">Preferences</div>\r\n        <button class=\"settings-nav-item active\" onclick=\"showSettingsPanel('appearance', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41\"/></svg>\r\n          Appearance\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('notifications', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9\"/><path d=\"M13.73 21a2 2 0 0 1-3.46 0\"/></svg>\r\n          Notifications\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('accessibility', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"4\" r=\"2\"/><path d=\"m6.5 8 5.5 1 5.5-1M12 9v5M9 22l1.5-4M15 22l-1.5-4\"/></svg>\r\n          Accessibility\r\n        </button>\r\n        <div class=\"settings-nav-group-label\">AI &amp; Relay</div>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('relay', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>\r\n          Relay &amp; AI\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('editor', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\r\n          Code Editor\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('keybindings', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"M6 8h.01M10 8h.01M14 8h.01M18 8h.01M8 12h.01M12 12h.01M16 12h.01M7 16h10\"/></svg>\r\n          Key Bindings\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('snippets-settings', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/><line x1=\"12\" y1=\"2\" x2=\"12\" y2=\"22\" stroke-dasharray=\"3,2\"/></svg>\r\n          Snippets\r\n        </button>\r\n\r\n        <div class=\"settings-nav-group-label\">Hether AI</div>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('ai-behavior', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 8v4l3 3\"/></svg>\r\n          AI Behavior\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('ai-persona', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>\r\n          AI Persona\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('ai-memory', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><ellipse cx=\"12\" cy=\"5\" rx=\"9\" ry=\"3\"/><path d=\"M21 12c0 1.66-4 3-9 3s-9-1.34-9-3\"/><path d=\"M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5\"/></svg>\r\n          AI Memory\r\n        </button>\r\n\r\n        <div class=\"settings-nav-group-label\">Privacy &amp; Data</div>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('privacy', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\r\n          Privacy\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('data', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><ellipse cx=\"12\" cy=\"5\" rx=\"9\" ry=\"3\"/><path d=\"M21 12c0 1.66-4 3-9 3s-9-1.34-9-3\"/><path d=\"M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5\"/></svg>\r\n          Data &amp; Storage\r\n        </button>\r\n\r\n        <div class=\"settings-nav-group-label\">Account</div>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('security', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\r\n          Security\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('sessions', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M8 21h8M12 17v4\"/></svg>\r\n          Sessions &amp; Devices\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('about', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\r\n          About\r\n        </button>\r\n\r\n        <div class=\"settings-nav-group-label\">Advanced</div>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('performance', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg>\r\n          Performance\r\n        </button>\r\n        <button class=\"settings-nav-item\" onclick=\"showSettingsPanel('network', this)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"9\" y=\"2\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"16\" y=\"16\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"2\" y=\"16\" width=\"6\" height=\"6\" rx=\"1\"/><path d=\"M12 8v3M5 16v-3a7 7 0 0 1 14 0v3\"/></svg>\r\n          Network &amp; Sync\r\n        </button>\r\n\r\n        <button class=\"settings-nav-item settings-nav-logout\" onclick=\"logOut()\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg>\r\n          Log out\r\n        </button>\r\n      </nav><div class=\"settings-scroll-thumb\" id=\"settingsScrollThumb\"></div></div>\r\n\r\n      <!-- \u2500\u2500 APPEARANCE \u2500\u2500 -->\r\n      <div class=\"settings-panel active\" id=\"panel-appearance\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Appearance</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Appearance</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Accent Color</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Accent Color</div>\r\n                <div class=\"setting-sub\">Choose the highlight color used across the app</div>\r\n              </div>\r\n              <div class=\"accent-swatch-row\">\r\n                <button class=\"accent-swatch\" id=\"accentSwatchBlue\" style=\"background:#6664c2;\" onclick=\"setAccentColor('blue')\" title=\"Blue\" aria-label=\"Blue accent\"></button>\r\n                <button class=\"accent-swatch\" id=\"accentSwatchGreen\" style=\"background:#21C063;\" onclick=\"setAccentColor('green')\" title=\"Green\" aria-label=\"Green accent\"></button>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Layout</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Squared Layout</div>\r\n                <div class=\"setting-sub\">Toggles square layout</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"squaredBubbleToggle\" onclick=\"toggleSquaredBubble()\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Inbox grouping\r\n                  <span style=\"display:inline-flex;align-items:center;gap:4px;margin-left:6px;padding:2px 7px;border-radius:20px;background:rgba(245,39,101,0.1);border:1px solid rgba(245,39,101,0.25);font-size:10px;font-weight:600;color:#F52765;letter-spacing:0.4px;vertical-align:middle;\">BETA</span>\r\n                </div>\r\n                <div class=\"setting-sub\">changes appearance and layout</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"inboxGroupingToggle\" onclick=\"toggleInboxGrouping()\"></button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 NOTIFICATIONS \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-notifications\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Notifications</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Notifications</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Alerts</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Push Notifications</div>\r\n                <div class=\"setting-sub\">Receive notifications about Hether updates and activity</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"notificationsToggle\" onclick=\"toggleNotifications()\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Sound</div>\r\n                <div class=\"setting-sub\">Play a sound for incoming messages and alerts</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"soundToggle\" onclick=\"toggleSound()\"></button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"settings-panel\" id=\"panel-relay\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Relay &amp; AI</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Relay &amp; AI</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Behavior</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Save relay history</div>\r\n                <div class=\"setting-sub\">Store conversations locally on this device</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"saveRelayToggle\" onclick=\"toggleSetting('saveRelay')\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Send on Enter</div>\r\n                <div class=\"setting-sub\">Press Enter to send; Shift+Enter for new line</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"enterSendToggle\" onclick=\"toggleSetting('enterSend')\"></button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">History</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Clear relay history</div>\r\n                <div class=\"setting-sub\">Remove all saved AI conversations from this device</div>\r\n              </div>\r\n              <button class=\"settings-btn danger\" onclick=\"clearHistory()\">Clear</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 CODE EDITOR \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-editor\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Code Editor</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Code Editor</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Preferences</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Auto-save</div>\r\n                <div class=\"setting-sub\">Automatically save editor content as you type</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"autosaveToggle\" onclick=\"toggleSetting('autosave')\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Line numbers</div>\r\n                <div class=\"setting-sub\">Show line numbers in the code editor gutter</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"lineNumbersToggle\" onclick=\"toggleSetting('lineNumbers')\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Word wrap</div>\r\n                <div class=\"setting-sub\">Wrap long lines instead of scrolling horizontally</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"wordWrapToggle\" onclick=\"toggleSetting('wordWrap')\"></button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 PRIVACY \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-privacy\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Privacy</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Privacy</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Session</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Ghost Mode\r\n                  <span style=\"display:inline-flex;align-items:center;gap:4px;margin-left:6px;padding:2px 7px;border-radius:20px;background:rgba(245,39,101,0.1);border:1px solid rgba(245,39,101,0.25);font-size:10px;font-weight:600;color:#F52765;letter-spacing:0.4px;vertical-align:middle;\">BETA</span>\r\n                </div>\r\n                <div class=\"setting-sub\">Relays in HetherGPT are not stored permanently. Some features may not function.</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"ghostModeToggle\" onclick=\"toggleGhostMode()\"></button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Legal</div>\r\n            <div class=\"setting-row clickable\" onclick=\"showModal('privacy')\">\r\n              <div>\r\n                <div class=\"setting-label\">Privacy Policy</div>\r\n                <div class=\"setting-sub\">How we collect, use, and protect your data</div>\r\n              </div>\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--text3)\" stroke-width=\"1.7\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n            </div>\r\n            <div class=\"setting-row clickable\" onclick=\"showModal('terms')\">\r\n              <div>\r\n                <div class=\"setting-label\">Terms of Service</div>\r\n                <div class=\"setting-sub\">Rules and usage guidelines for Hether</div>\r\n              </div>\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--text3)\" stroke-width=\"1.7\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 DATA & STORAGE \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-data\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Data &amp; Storage</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Data &amp; Storage</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Usage</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Local storage usage</div>\r\n                <div class=\"setting-sub\" id=\"storageUsageText\">Calculating\u2026</div>\r\n              </div>\r\n              <button class=\"settings-btn\" onclick=\"calcStorageUsage()\">Refresh</button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Export</div>\r\n            <div class=\"setting-row clickable\" onclick=\"exportData()\">\r\n              <div>\r\n                <div class=\"setting-label\">Export my data</div>\r\n                <div class=\"setting-sub\">Download your notes and relay history as a JSON file</div>\r\n              </div>\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--text3)\" stroke-width=\"1.7\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Danger Zone</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Clear all local data</div>\r\n                <div class=\"setting-sub\">Permanently wipe notes, history, and preferences from this device</div>\r\n              </div>\r\n              <button class=\"settings-btn danger\" onclick=\"clearAllData()\">Wipe</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 SECURITY \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-security\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Security</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Security</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Access</div>\r\n            <div class=\"setting-row clickable\" onclick=\"openVaultPopup()\">\r\n              <div>\r\n                <div class=\"setting-label\">Admin Key <span style=\"font-size:12px;color:var(--text3);font-weight:400;\">(Authorized Personnel Only)</span></div>\r\n                <div class=\"setting-sub\">Restricted access \u2014 requires valid credentials</div>\r\n              </div>\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--text3)\" stroke-width=\"1.7\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n            </div>\r\n            <div class=\"setting-row clickable\" onclick=\"openVaultTerminal()\">\r\n              <div>\r\n                <div class=\"setting-label\">Admin Terminal <span style=\"font-size:12px;color:var(--text3);font-weight:400;\">(Authorized Personnel Only)</span></div>\r\n                <div class=\"setting-sub\">Execute privileged commands \u2014 restricted access</div>\r\n              </div>\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--text3)\" stroke-width=\"1.7\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Information</div>\r\n            <div class=\"setting-row clickable\" onclick=\"showModal('security')\">\r\n              <div>\r\n                <div class=\"setting-label\">Security Information</div>\r\n                <div class=\"setting-sub\">How your data is encrypted and protected</div>\r\n              </div>\r\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--text3)\" stroke-width=\"1.7\"><polyline points=\"9 18 15 12 9 6\"/></svg>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 ABOUT \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-about\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">About</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">About</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">App</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">hether</div>\r\n                <div class=\"setting-sub\">Version 7.8 \u2014 AI assistant &amp; code n' arcade</div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 KEY BINDINGS \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-keybindings\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Key Bindings</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Key Bindings</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Editor Actions</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Run code</div>\r\n                <div class=\"setting-sub\">Execute the current file or selection</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbRunDisplay\" onclick=\"startRebind('kbRun', this)\">\r\n                <kbd id=\"kbRunLabel\">Ctrl+Enter</kbd>\r\n              </div>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Format code</div>\r\n                <div class=\"setting-sub\">Auto-indent and format the current file</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbFormatDisplay\" onclick=\"startRebind('kbFormat', this)\">\r\n                <kbd id=\"kbFormatLabel\">Alt+Shift+F</kbd>\r\n              </div>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Save file</div>\r\n                <div class=\"setting-sub\">Save the current editor file</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbSaveDisplay\" onclick=\"startRebind('kbSave', this)\">\r\n                <kbd id=\"kbSaveLabel\">Ctrl+S</kbd>\r\n              </div>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Toggle comment</div>\r\n                <div class=\"setting-sub\">Comment or uncomment the selected lines</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbCommentDisplay\" onclick=\"startRebind('kbComment', this)\">\r\n                <kbd id=\"kbCommentLabel\">Ctrl+/</kbd>\r\n              </div>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Find in file</div>\r\n                <div class=\"setting-sub\">Open the in-editor search bar</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbFindDisplay\" onclick=\"startRebind('kbFind', this)\">\r\n                <kbd id=\"kbFindLabel\">Ctrl+F</kbd>\r\n              </div>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Duplicate line</div>\r\n                <div class=\"setting-sub\">Copy the current line below</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbDupDisplay\" onclick=\"startRebind('kbDup', this)\">\r\n                <kbd id=\"kbDupLabel\">Ctrl+D</kbd>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Navigation</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Go to line</div>\r\n                <div class=\"setting-sub\">Jump to a specific line number</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbGotoDisplay\" onclick=\"startRebind('kbGoto', this)\">\r\n                <kbd id=\"kbGotoLabel\">Ctrl+G</kbd>\r\n              </div>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Switch view</div>\r\n                <div class=\"setting-sub\">Cycle between editor, relay, and notes</div>\r\n              </div>\r\n              <div class=\"kbd-combo\" id=\"kbSwitchDisplay\" onclick=\"startRebind('kbSwitch', this)\">\r\n                <kbd id=\"kbSwitchLabel\">Ctrl+Tab</kbd>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Reset</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Reset all key bindings</div>\r\n                <div class=\"setting-sub\">Restore all shortcuts to their default values</div>\r\n              </div>\r\n              <button class=\"settings-btn danger\" onclick=\"resetKeybindings()\">Reset</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 SNIPPETS SETTINGS \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-snippets-settings\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Snippets</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Snippets</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Display</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Show language badges</div>\r\n                <div class=\"setting-sub\">Display the language tag on each snippet card</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"snippetBadgesToggle\" onclick=\"toggleSetting('snippetBadges')\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Syntax highlighting</div>\r\n                <div class=\"setting-sub\">Apply color-coding inside snippet previews</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"snippetHighlightToggle\" onclick=\"toggleSetting('snippetHighlight')\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Compact snippet cards</div>\r\n                <div class=\"setting-sub\">Reduce the preview height of each snippet</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"snippetCompactToggle\" onclick=\"toggleSetting('snippetCompact')\"></button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Behavior</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Copy on single click</div>\r\n                <div class=\"setting-sub\">Click a snippet to instantly copy it to clipboard</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"snippetClickCopyToggle\" onclick=\"toggleSetting('snippetClickCopy')\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Open in editor on double-click</div>\r\n                <div class=\"setting-sub\">Double-clicking a snippet loads it into the code editor</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"snippetDoubleOpenToggle\" onclick=\"toggleSetting('snippetDoubleOpen')\"></button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 AI BEHAVIOR \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-ai-behavior\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">AI Behavior</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">AI Behavior</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Relay</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Save relay history</div>\r\n                <div class=\"setting-sub\">Store conversations locally on this device</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"saveRelayToggle2\" onclick=\"toggleSettingDup('saveRelay', this)\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Send on Enter</div>\r\n                <div class=\"setting-sub\">Press Enter to send; Shift+Enter for new line</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"enterSendToggle2\" onclick=\"toggleSettingDup('enterSend', this)\"></button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">History</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Clear relay history</div>\r\n                <div class=\"setting-sub\">Remove all saved AI conversations from this device</div>\r\n              </div>\r\n              <button class=\"settings-btn danger\" onclick=\"clearHistory()\">Clear</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 AI PERSONA \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-ai-persona\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">AI Persona</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">AI Persona</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Custom Instructions</div>\r\n            <div class=\"setting-row\" style=\"flex-direction:column;align-items:flex-start;gap:8px;\">\r\n              <div>\r\n                <div class=\"setting-label\">System prompt</div>\r\n                <div class=\"setting-sub\">Custom instructions saved locally \u2014 copy these into your AI messages manually or pass them to your backend</div>\r\n              </div>\r\n              <textarea class=\"settings-textarea\" id=\"aiSystemPrompt\" placeholder=\"e.g. Always respond in Python. Prefer functional style.\" oninput=\"saveTextareaSetting('aiSystemPrompt', this.value)\"></textarea>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Welcome Greeting</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Personalized greeting</div>\r\n                <div class=\"setting-sub\">Show your name in the welcome message on new relays</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"personalGreetToggle\" onclick=\"togglePersonalGreet()\"></button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 AI MEMORY \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-ai-memory\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">AI Memory</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">AI Memory</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Stored Memory</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Memory entries</div>\r\n                <div class=\"setting-sub\" id=\"aiMemoryCountText\">Calculating\u2026</div>\r\n              </div>\r\n              <button class=\"settings-btn\" onclick=\"calcAiMemoryCount()\">Refresh</button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Clear AI memory</div>\r\n                <div class=\"setting-sub\">Erase everything Hether AI has remembered about you</div>\r\n              </div>\r\n              <button class=\"settings-btn danger\" onclick=\"clearAiMemory()\">Clear</button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Notes</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Notes count</div>\r\n                <div class=\"setting-sub\" id=\"aiNotesCountText\">Calculating\u2026</div>\r\n              </div>\r\n              <button class=\"settings-btn\" onclick=\"calcNotesCount()\">Refresh</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 ACCESSIBILITY \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-accessibility\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Accessibility</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Accessibility</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Visual</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Font size</div>\r\n                <div class=\"setting-sub\">Adjust base text size across the interface</div>\r\n              </div>\r\n              <select class=\"settings-select\" id=\"a11yFontSize\" onchange=\"applyFontSize(this.value)\">\r\n                <option value=\"13\">Small (13px)</option>\r\n                <option value=\"14\" selected>Default (14px)</option>\r\n                <option value=\"16\">Large (16px)</option>\r\n                <option value=\"18\">Extra Large (18px)</option>\r\n              </select>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">High contrast mode</div>\r\n                <div class=\"setting-sub\">Increase border and text contrast for readability</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"highContrastToggle\" onclick=\"toggleHighContrast()\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Reduce motion</div>\r\n                <div class=\"setting-sub\">Disable animations and transitions throughout the app</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"reduceMotionToggle\" onclick=\"toggleReduceMotion()\"></button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Input</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Focus ring always visible</div>\r\n                <div class=\"setting-sub\">Always show keyboard focus outlines on interactive elements</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"focusRingToggle\" onclick=\"toggleFocusRing()\"></button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 SESSIONS & DEVICES \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-sessions\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Sessions &amp; Devices</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Sessions &amp; Devices</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Active Session</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Current device</div>\r\n                <div class=\"setting-sub\" id=\"sessionDeviceText\">Detecting\u2026</div>\r\n              </div>\r\n              <span style=\"font-size:11px;padding:3px 8px;border-radius:20px;background:rgba(34,197,94,0.12);border:1px solid rgba(34,197,94,0.3);color:#22c55e;font-weight:600;\">Active</span>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Session started</div>\r\n                <div class=\"setting-sub\" id=\"sessionStartText\">\u2014</div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 PERFORMANCE \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-performance\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Performance</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Performance</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Rendering</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Animate message bubbles</div>\r\n                <div class=\"setting-sub\">Slide-in animation for new relay messages</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"msgAnimToggle\" onclick=\"toggleMsgAnim()\"></button>\r\n            </div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Background blur effects</div>\r\n                <div class=\"setting-sub\">Enable frosted-glass blur on overlays and popups</div>\r\n              </div>\r\n              <button class=\"toggle\" id=\"blurEffectsToggle\" onclick=\"toggleBlurEffects()\"></button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Diagnostics</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Memory usage</div>\r\n                <div class=\"setting-sub\" id=\"perfMemText\">Calculating\u2026</div>\r\n              </div>\r\n              <button class=\"settings-btn\" onclick=\"calcPerfStats()\">Refresh</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- \u2500\u2500 NETWORK & SYNC \u2500\u2500 -->\r\n      <div class=\"settings-panel\" id=\"panel-network\">\r\n        <div class=\"mob-settings-panel-header\">\r\n          <button class=\"mob-settings-back-btn\" onclick=\"mobSettingsBack()\" aria-label=\"Back\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg></button>\r\n          <span class=\"mob-panel-title\">Network &amp; Sync</span>\r\n        </div>\r\n        <div class=\"settings-panel-inner\">\r\n          <div class=\"settings-panel-title\">Network &amp; Sync</div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Connection</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Connection status</div>\r\n                <div class=\"setting-sub\" id=\"networkStatusText\">Click Check to test</div>\r\n              </div>\r\n              <button class=\"settings-btn\" onclick=\"checkNetworkStatus()\">Check</button>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"settings-section\">\r\n            <div class=\"settings-section-label\">Cache</div>\r\n            <div class=\"setting-row\">\r\n              <div>\r\n                <div class=\"setting-label\">Clear network cache</div>\r\n                <div class=\"setting-sub\">Remove cached API responses and media thumbnails</div>\r\n              </div>\r\n              <button class=\"settings-btn\" onclick=\"clearNetworkCache()\">Clear</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n    </div><!-- end settings-body -->\r\n  </div>\r\n\r\n  <!-- MODAL for Privacy / Terms / Security -->\r\n  <div class=\"overlay\" id=\"infoModalOverlay\" onclick=\"closeInfoModal()\">\r\n    <div class=\"popup\" style=\"width:min(520px,95vw);max-height:80vh;overflow-y:auto;\" onclick=\"event.stopPropagation()\">\r\n      <h3 id=\"infoModalTitle\" style=\"margin-bottom:12px;\"></h3>\r\n      <div id=\"infoModalBody\" style=\"font-size:13px;line-height:1.7;color:var(--text2);max-height:55vh;overflow-y:auto;\"></div>\r\n      <div class=\"popup-btns\" style=\"margin-top:16px;\">\r\n        <button class=\"btn-confirm\" onclick=\"closeInfoModal()\">Close</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n</main>\r\n\r\n<!-- COMPANION AI POPUP -->\r\n<div class=\"companion-popup\" id=\"companionPopup\">\r\n  <!-- Titlebar -->\r\n  <div class=\"companion-titlebar\">\r\n    <span class=\"companion-titlebar-label\">Hether \u2014 AI Companion</span>\r\n    <button class=\"companion-titlebar-close\" onclick=\"closeCompanion()\" title=\"Close\">\u00d7</button>\r\n  </div>\r\n  <div class=\"companion-relay-header\">\r\n    <div style=\"width:28px;height:28px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\r\n      <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/></svg>\r\n    </div>\r\n    <div>\r\n      <div style=\"font-size:13.5px;font-weight:600;color:var(--text);line-height:1.2;\">Hether AI</div>\r\n      <div style=\"font-size:11px;color:var(--text3);line-height:1.2;\">AI Companion</div>\r\n    </div>\r\n  </div>\r\n  <div class=\"companion-messages\" id=\"companionMessages\"></div>\r\n  <!-- Input -->\r\n  <div class=\"companion-input-area\">\r\n    <div class=\"companion-input-row\">\r\n      <button class=\"emoji-btn\" style=\"flex-shrink:0;opacity:0.5;cursor:default;\" tabindex=\"-1\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" x2=\"9.01\" y1=\"9\" y2=\"9\"/><line x1=\"15\" x2=\"15.01\" y1=\"9\" y2=\"9\"/></svg>\r\n      </button>\r\n      <textarea id=\"companionInput\" placeholder=\"Message\u2026\" rows=\"1\"\r\n        oninput=\"autoResizeCompanion(this)\"\r\n        onkeydown=\"companionHandleKey(event)\"></textarea>\r\n      <button class=\"companion-send-btn\" id=\"companionSendBtn\" onclick=\"sendCompanionMessage()\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><line x1=\"22\" y1=\"2\" x2=\"11\" y2=\"13\"/><polygon points=\"22 2 15 22 11 13 2 9 22 2\"/></svg>\r\n      </button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"flux-overlay\" id=\"fluxOverlay\" onclick=\"fluxOverlayClick(event)\">\r\n  <div class=\"flux-popup\" id=\"fluxPopup\">\r\n\r\n    <!-- Title bar -->\r\n    <div class=\"flux-titlebar\">\r\n      <span class=\"flux-titlebar-label\">Hether</span>\r\n      <div class=\"flux-titlebar-controls\">\r\n        <button class=\"flux-titlebar-ai-btn\" id=\"fluxAiToggleBtn\" onclick=\"toggleFluxAiPanel()\" title=\"AI Assistant\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/></svg>\r\n        </button>\r\n        <button class=\"flux-titlebar-close\" onclick=\"closeFLUX()\" title=\"Close\">\u00d7</button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Body: sidebar + right panel -->\r\n    <div class=\"flux-body\">\r\n      <div class=\"flux-sidebar\">\r\n        <div class=\"flux-sidebar-header\" id=\"fluxSidebarHeader\">\r\n          <div class=\"flux-sidebar-title\" id=\"fluxSidebarTitle\">\r\n            Messages\r\n            <span class=\"flux-secure-badge\">SECURE</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"flux-group-add-view\" id=\"fluxGroupAddView\">\r\n          <div class=\"flux-group-add-header\">\r\n            <button class=\"flux-group-add-back\" type=\"button\" onclick=\"handleFluxGroupAddBack()\" aria-label=\"Back\" title=\"Back\">\r\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m15 18-6-6 6-6\"/></svg>\r\n            </button>\r\n            <div class=\"flux-group-add-title\" id=\"fluxGroupAddTitle\">Add group</div>\r\n            <button class=\"flux-group-create-top\" id=\"fluxGroupCreateTopBtn\" type=\"button\" onclick=\"handleFluxGroupAddSubmit()\" aria-label=\"Create group\" title=\"Create group\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14\"/><path d=\"m12 5 7 7-7 7\"/></svg>\r\n            </button>\r\n          </div>\r\n          <div class=\"flux-group-add-search\"><input id=\"fluxGroupMemberSearch\" class=\"pdp-input\" type=\"text\" placeholder=\"Search username...\" autocomplete=\"off\" oninput=\"searchFluxGroupMembers(this.value)\" onkeydown=\"handleFluxGroupMemberSearchKeydown(event)\"></div>\r\n          <div class=\"flux-group-draft\" id=\"fluxGroupDraftMembers\"></div>\r\n          <div class=\"flux-group-results\" id=\"fluxGroupMemberResults\"></div>\r\n          <button class=\"flux-group-create\" id=\"fluxGroupCreateBtn\" type=\"button\" onclick=\"handleFluxGroupAddSubmit()\">Create group</button>\r\n        </div>\r\n\r\n        <div class=\"flux-search-wrap\">\r\n          <div class=\"flux-search-input-row\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n            <input type=\"text\" id=\"fluxSearchInput\" placeholder=\"Search users...\" oninput=\"onFluxSearch(this.value)\" onkeydown=\"if(event.key==='Enter'){event.preventDefault();onFluxSearchEnter(this.value,'desktop');}\" autocomplete=\"off\">\r\n          </div>\r\n          <div class=\"flux-search-dropdown\" id=\"fluxSearchDropdown\"></div>\r\n        </div>\r\n\r\n        <div class=\"flux-tab-bar\" id=\"fluxTabBar\">\r\n          <button class=\"flux-tab-btn active\" data-tab=\"primary\" onclick=\"switchFluxTab('primary','desktop')\">Primary <span class=\"flux-tab-count\" id=\"fluxPrimaryCount\" data-zero=\"true\">0</span></button>\r\n          <button class=\"flux-tab-btn\" data-tab=\"general\" onclick=\"switchFluxTab('general','desktop')\">General <span class=\"flux-tab-count\" id=\"fluxGeneralCount\" data-zero=\"true\">0</span></button>\r\n          <button class=\"flux-tab-btn\" data-tab=\"all\" onclick=\"switchFluxTab('all','desktop')\">All</button>\r\n        </div>\r\n\r\n        <div class=\"flux-sidebar-load-bar\" id=\"fluxSidebarLoadBar\"><div class=\"flux-load-bar-fill\" id=\"fluxSidebarLoadFill\"></div></div>\r\n\r\n        <div class=\"flux-conv-list\" id=\"fluxConvList\"></div>\r\n      </div>\r\n    <div class=\"flux-relay-panel\" id=\"fluxRelayPanel\">\r\n      <div class=\"flux-relay-content\">\r\n        <div class=\"flux-empty-state\" id=\"fluxEmptyState\">\r\n          <svg width=\"48\" height=\"48\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>\r\n          <p>Select a conversation</p>\r\n        </div>\r\n        <div id=\"fluxActiveRelayWrap\" style=\"display:none;position:relative;\">\r\n          <div class=\"flux-clearing-overlay\" id=\"fluxClearingOverlay\">\r\n            <div class=\"flux-clearing-label\">Getting things done\u2026</div>\r\n            <div class=\"flux-clearing-bar-wrap\">\r\n              <div class=\"flux-clearing-bar-fill\" id=\"fluxClearingBarFill\"></div>\r\n            </div>\r\n          </div>\r\n          <div class=\"flux-relay-topbar\" id=\"fluxRelayTopbar\">\r\n            <div style=\"position:relative;flex-shrink:0;cursor:pointer;\" onclick=\"openNicknamePanel()\">\r\n              <div class=\"flux-relay-topbar-avatar\" id=\"fluxTopbarAvatar\"></div>\r\n              <span class=\"flux-presence-dot offline\" id=\"fluxPresenceDot\"></span>\r\n            </div>\r\n            <div class=\"flux-relay-topbar-info\" onclick=\"openNicknamePanel()\">\r\n              <div class=\"flux-relay-topbar-name\" id=\"fluxTopbarName\"></div>\r\n              <div id=\"fluxTopbarUsername\" style=\"font-size:11.5px;color:var(--text2);line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;\"></div>\r\n            </div>\r\n            <button class=\"flux-group-mute-btn\" id=\"fluxGroupMuteBtn\" onclick=\"toggleActiveFluxGroupMute()\" title=\"Mute group\" aria-label=\"Mute group\">\r\n              <svg id=\"fluxGroupMuteIcon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n                <path d=\"M8.7 3A6 6 0 0 1 18 8c0 2.1.8 3.9 1.6 5.2\"/>\r\n                <path d=\"M17 17H3s3-2 3-9c0-.7.1-1.4.3-2\"/>\r\n                <path d=\"M10.3 21a1.94 1.94 0 0 0 3.4 0\"/>\r\n                <path d=\"m2 2 20 20\"/>\r\n              </svg>\r\n            </button>\r\n            <button class=\"flux-delete-relay-btn\" id=\"fluxDeleteRelayBtn\" onclick=\"handleFluxHeaderClear()\" title=\"Clear relay (Alt+Backspace)\" aria-label=\"Clear relay\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide-badge-x-icon\"><path d=\"M3.85 8.62a4 4 0 0 1 4.78-4.77 4 4 0 0 1 6.74 0 4 4 0 0 1 4.78 4.78 4 4 0 0 1 0 6.74 4 4 0 0 1-4.77 4.78 4 4 0 0 1-6.75 0 4 4 0 0 1-4.78-4.77 4 4 0 0 1 0-6.76Z\"/><line x1=\"15\" x2=\"9\" y1=\"9\" y2=\"15\"/><line x1=\"9\" x2=\"15\" y1=\"9\" y2=\"15\"/></svg>\r\n            </button>\r\n                        <button class=\"flux-delete-relay-btn flux-group-menu-btn\" id=\"fluxHeaderMoreBtn\" onclick=\"openFluxHeaderMoreMenu(event)\" title=\"More options\" aria-label=\"More options\" style=\"display:none;\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"5\" r=\"1\"/><circle cx=\"12\" cy=\"19\" r=\"1\"/></svg>\r\n            </button>\r\n            \r\n<button class=\"flux-unarchive-btn\" id=\"fluxUnarchiveBtn\" onclick=\"confirmUnarchiveActive()\" title=\"Unarchive\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"5\" rx=\"1\"/><path d=\"M5 9v9a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V9\"/><polyline points=\"9 13 12 10 15 13\"/><line x1=\"12\" y1=\"10\" x2=\"12\" y2=\"17\"/></svg>\r\n            </button>\r\n          </div>\r\n\r\n          <div class=\"flux-relay-load-bar\" id=\"fluxRelayLoadBar\"><div class=\"flux-load-bar-fill\" id=\"fluxRelayLoadFill\"></div></div>\r\n\r\n          <div class=\"flux-relay-messages\" id=\"fluxRelayMessages\"></div>\r\n\r\n          <div class=\"flux-media-staging-wrap\" id=\"fluxMediaStagingWrap\">\r\n            <div class=\"flux-media-staging-inner\">\r\n              <div class=\"flux-media-staging-thumb\" id=\"fluxMediaStagingThumb\"></div>\r\n              <span style=\"font-size:12px;color:var(--text2);\">Image ready to send</span>\r\n            </div>\r\n            <button class=\"flux-reply-cancel\" onclick=\"clearFluxStaging()\" title=\"Remove image\">\u00d7</button>\r\n          </div>\r\n\r\n          <div class=\"flux-edit-bar\" id=\"fluxEditBar\">\r\n            <div class=\"flux-edit-bar-label\">\r\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"12\" height=\"12\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\r\n              Editing\r\n            </div>\r\n            <div class=\"flux-edit-bar-text\" id=\"fluxEditBarText\"></div>\r\n            <button class=\"flux-reply-cancel\" onclick=\"cancelEdit('desktop')\" title=\"Cancel edit\">\u00d7</button>\r\n          </div>\r\n\r\n          <div class=\"flux-reply-bar\" id=\"fluxReplyBar\">\r\n            <div style=\"display:flex;align-items:center;gap:6px;color:var(--accent);font-size:11.5px;font-weight:600;margin-bottom:2px;\">\r\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"12\" height=\"12\"><polyline points=\"9 17 4 12 9 7\"/><path d=\"M20 18v-2a4 4 0 0 0-4-4H4\"/></svg>\r\n              Replying to\r\n            </div>\r\n            <div class=\"flux-reply-bar-content\">\r\n              <div class=\"flux-reply-bar-author\" id=\"fluxReplyBarAuthor\"></div>\r\n              <div class=\"flux-reply-bar-text\" id=\"fluxReplyBarText\"></div>\r\n            </div>\r\n            <img class=\"flux-reply-bar-thumb\" id=\"fluxReplyBarThumb\" style=\"display:none;\" alt=\"\">\r\n            <button class=\"flux-reply-cancel\" onclick=\"cancelReply()\">\u00d7</button>\r\n          </div>\r\n\r\n          <div class=\"flux-relay-input-area\">\r\n            <div class=\"flux-input-row\">\r\n              <button class=\"emoji-btn\" id=\"fluxEmojiBtn\" onclick=\"toggleEmojiPicker('flux')\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" x2=\"9.01\" y1=\"9\" y2=\"9\"/><line x1=\"15\" x2=\"15.01\" y1=\"9\" y2=\"9\"/></svg>\r\n              </button>\r\n              <textarea id=\"fluxInput\" placeholder=\"Message\u2026\" oninput=\"onFluxInputChange('desktop'); autoResizeFlux(this)\" onfocus=\"onFluxInputFocus('desktop')\" onblur=\"onFluxInputBlur('desktop')\" onkeydown=\"onFluxKeypress(event,'desktop'); fluxHandleKey(event,'desktop')\" onpaste=\"handleFluxPaste(event,'desktop')\" rows=\"1\"></textarea>\r\n              <label class=\"emoji-btn\" id=\"fluxMediaBtn\" for=\"fluxMediaUpload\" title=\"Send media\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect width=\"18\" height=\"18\" x=\"3\" y=\"3\" rx=\"5\" ry=\"5\"/><circle cx=\"9\" cy=\"9\" r=\"2\"/><path d=\"m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21\"/></svg>\r\n              </label>\r\n              <input type=\"file\" id=\"fluxMediaUpload\" accept=\"image/*,video/*\" style=\"display:none\" onchange=\"stageFluxMedia(event,'desktop')\">\r\n              <button class=\"flux-send-btn hidden\" id=\"fluxSendBtn\" onclick=\"fluxSend('desktop')\">\r\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><line x1=\"22\" y1=\"2\" x2=\"11\" y2=\"13\"/><polygon points=\"22 2 15 22 11 13 2 9 22 2\"/></svg>\r\n              </button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n\r\n      <div class=\"flux-profile-tab\" id=\"fluxProfileTab\">\r\n       <div class=\"flux-profile-tab-inner\" id=\"fluxProfileTabInner\">\r\n        <div class=\"flux-profile-tab-header\">\r\n          <div class=\"flux-profile-tab-title\" id=\"fluxProfileTabTitle\">Profile</div>\r\n          <div style=\"display:flex;align-items:center;gap:4px;\">\r\n            <button class=\"flux-profile-tab-close flux-group-settings-btn\" id=\"fluxGroupSettingsBtn\" onclick=\"openFluxGroupSettings()\" title=\"Group settings\" aria-label=\"Group settings\" style=\"display:none;\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-bolt-icon lucide-bolt\"><path d=\"M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg>\r\n            </button>\r\n            <button class=\"flux-profile-tab-close\" onclick=\"closeNicknamePanel()\" title=\"Close\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"15 18 9 12 15 6\"/></svg>\r\n          </button>\r\n          </div>\r\n        </div>\r\n        <div class=\"flux-profile-tab-avatar default-avatar\" id=\"fluxProfileTabAvatar\" onclick=\"openGroupAvatarMenu(event)\"></div>\r\n        <div class=\"flux-profile-tab-name-wrap\" id=\"fluxGroupNameRow\">\r\n          <div class=\"flux-profile-tab-name\" id=\"fluxProfileTabName\">User</div>\r\n          <button class=\"flux-group-name-edit\" id=\"fluxGroupNameEditBtn\" onclick=\"showGroupNameEditor()\" title=\"Change group name\" style=\"display:none;\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-tags-icon lucide-tags\"><path d=\"M13.172 2a2 2 0 0 1 1.414.586l6.71 6.71a2.4 2.4 0 0 1 0 3.408l-4.592 4.592a2.4 2.4 0 0 1-3.408 0l-6.71-6.71A2 2 0 0 1 6 9.172V3a1 1 0 0 1 1-1z\"/><path d=\"M2 7v6.172a2 2 0 0 0 .586 1.414l6.71 6.71a2.4 2.4 0 0 0 3.191.193\"/><circle cx=\"10.5\" cy=\"6.5\" r=\".5\" fill=\"currentColor\"/></svg>\r\n          </button>\r\n        </div>\r\n        <div class=\"flux-profile-tab-username\" id=\"fluxProfileTabUsername\">username</div>\r\n\r\n        <div class=\"flux-group-name-editor\" id=\"fluxGroupNameEditor\" style=\"display:none;\">\r\n          <input type=\"text\" class=\"flux-nickname-input\" id=\"fluxGroupNameInput\" placeholder=\"Group name\" maxlength=\"80\" onkeydown=\"groupNameInputKey(event)\">\r\n          <div class=\"flux-nickname-editor-btns\">\r\n            <button class=\"btn-cancel\" style=\"padding:6px 12px;font-size:12.5px;\" onclick=\"hideGroupNameEditor()\">Cancel</button>\r\n            <button class=\"btn-confirm\" style=\"padding:6px 14px;font-size:12.5px;\" onclick=\"commitGroupName()\">Save</button>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"flux-nickname-editor\" id=\"fluxNicknameEditor\" style=\"display:none;margin-top:14px;\">\r\n          <input type=\"text\" class=\"flux-nickname-input\" id=\"fluxNicknameInput\" placeholder=\"Nickname\" maxlength=\"40\" onkeydown=\"nicknameInputKey(event)\">\r\n          <div class=\"flux-nickname-editor-btns\">\r\n            <button class=\"flux-nickname-clear-btn\" id=\"fluxNicknameClearBtn\" onclick=\"clearNickname()\">Remove</button>\r\n            <div style=\"display:flex;gap:6px;margin-left:auto;\">\r\n              <button class=\"btn-cancel\" style=\"padding:6px 12px;font-size:12.5px;\" onclick=\"hideNicknameEditor()\">Cancel</button>\r\n              <button class=\"btn-confirm\" style=\"padding:6px 14px;font-size:12.5px;\" onclick=\"commitNickname()\">Save</button>\r\n            </div>\r\n          </div>\r\n          <div class=\"flux-nickname-hint\">Only visible to you</div>\r\n        </div>\r\n\r\n        <button class=\"flux-nickname-edit-btn\" id=\"fluxProfileCloseBtn\" onclick=\"closeNicknamePanel()\" style=\"margin:14px auto 0;\">\r\n          Close\r\n        </button>\r\n\r\n        <div class=\"flux-profile-tab-divider\" style=\"height:1px;background:var(--border);margin:16px 5px;flex-shrink:0;\"></div>\r\n\r\n        <!-- Mutual names section (DMs only) -->\r\n        <div class=\"flux-mutual-section\" id=\"fluxMutualSection\">\r\n          <div class=\"flux-mutual-row\">\r\n            <div class=\"flux-mutual-avatar\" id=\"fluxMutualTheirAvatar\"></div>\r\n            <div class=\"flux-mutual-name-col\">\r\n              <div class=\"flux-mutual-name-wrap\">\r\n                <div class=\"flux-mutual-name\" id=\"fluxMutualTheirName\">User</div>\r\n                <button class=\"flux-mutual-edit-pencil\" onclick=\"showNicknameEditor()\" title=\"Edit nickname\">\r\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-tags-icon lucide-tags\"><path d=\"M13.172 2a2 2 0 0 1 1.414.586l6.71 6.71a2.4 2.4 0 0 1 0 3.408l-4.592 4.592a2.4 2.4 0 0 1-3.408 0l-6.71-6.71A2 2 0 0 1 6 9.172V3a1 1 0 0 1 1-1z\"/><path d=\"M2 7v6.172a2 2 0 0 0 .586 1.414l6.71 6.71a2.4 2.4 0 0 0 3.191.193\"/><circle cx=\"10.5\" cy=\"6.5\" r=\".5\" fill=\"currentColor\"/></svg>\r\n                </button>\r\n              </div>\r\n              <div class=\"flux-mutual-username\" id=\"fluxMutualTheirUsername\">username</div>\r\n            </div>\r\n          </div>\r\n          <div class=\"flux-mutual-row\">\r\n            <div class=\"flux-mutual-avatar\" id=\"fluxMutualMyAvatar\"></div>\r\n            <div class=\"flux-mutual-name-col\">\r\n              <div class=\"flux-mutual-name-wrap\">\r\n                <div class=\"flux-mutual-name\" id=\"fluxMutualMyName\">You</div>\r\n              </div>\r\n              <div class=\"flux-mutual-username\" id=\"fluxMutualMyUsername\">username</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Group members section (groups only) -->\r\n        <div class=\"flux-mutual-section\" id=\"fluxGroupMembersSection\" style=\"display:none;\">\r\n          <div style=\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:var(--text3);padding:0 5px 8px;\">Members</div>\r\n          <div id=\"fluxGroupMembersList\"></div>\r\n        </div>\r\n\r\n        <div class=\"flux-profile-tab-divider\" style=\"height:1px;background:var(--border);margin:16px 10px;flex-shrink:0;\"></div>\r\n\r\n        <button class=\"flux-theme-toggle-btn\" id=\"fluxThemeToggleBtn\" onclick=\"toggleThemePicker()\">\r\n          <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 2a10 10 0 0 1 0 20C6.48 22 2 17.52 2 12\"/><path d=\"M12 8v4l3 3\"/></svg>\r\n          Theme\r\n          <svg id=\"fluxThemeChevron\" width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"transition:transform 0.2s;\"><polyline points=\"6 9 12 15 18 9\"/></svg>\r\n        </button>\r\n\r\n        <div class=\"flux-theme-picker\" id=\"fluxThemePicker\">\r\n          <!-- populated by JS -->\r\n        </div>\r\n\r\n       </div>\r\n      </div>\r\n\r\n    </div>\r\n\r\n    <div class=\"flux-ai-panel\" id=\"fluxAiPanel\">\r\n      <div class=\"flux-relay-topbar\" style=\"border-bottom:1px solid var(--border);flex-shrink:0;background:var(--surface);position:relative;z-index:2;\">\r\n        <div style=\"display:flex;align-items:center;gap:8px;flex:1;\">\r\n          <div style=\"width:28px;height:28px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div style=\"font-size:13.5px;font-weight:600;color:var(--text);line-height:1.2;\">Hether AI</div>\r\n            <div style=\"font-size:11px;color:var(--text3);line-height:1.2;\">AI Assistant</div>\r\n          </div>\r\n        </div>\r\n        <button onclick=\"newFluxAiRelay()\" title=\"New relay\" style=\"background:none;border:none;cursor:pointer;padding:6px;border-radius:8px;color:var(--text2);display:flex;align-items:center;justify-content:center;transition:background 0.15s;\" onmouseover=\"this.style.background='var(--surface2)'\" onmouseout=\"this.style.background='none'\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 18V5\"/><path d=\"M15 13a4.17 4.17 0 0 1-3-4 4.17 4.17 0 0 1-3 4\"/><path d=\"M17.598 6.5A3 3 0 1 0 12 5a3 3 0 1 0-5.598 1.5\"/><path d=\"M17.997 5.125a4 4 0 0 1 2.526 5.77\"/><path d=\"M18 18a4 4 0 0 0 2-7.464\"/><path d=\"M19.967 17.483A4 4 0 1 1 12 18a4 4 0 1 1-7.967-.517\"/><path d=\"M6 18a4 4 0 0 1-2-7.464\"/><path d=\"M6.003 5.125a4 4 0 0 0-2.526 5.77\"/></svg>\r\n        </button>\r\n      </div>\r\n      <div class=\"flux-ai-messages\" id=\"fluxAiMessages\"></div>\r\n      <div class=\"flux-ai-input-area\">\r\n        <div class=\"flux-ai-input-row\">\r\n          <button class=\"emoji-btn\" style=\"flex-shrink:0;\" disabled title=\"Emoji\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" x2=\"9.01\" y1=\"9\" y2=\"9\"/><line x1=\"15\" x2=\"15.01\" y1=\"9\" y2=\"9\"/></svg>\r\n          </button>\r\n          <textarea id=\"fluxAiInput\" placeholder=\"Message\u2026\" rows=\"1\"\r\n            oninput=\"autoResizeFluxAi(this)\"\r\n            onkeydown=\"fluxAiHandleKey(event)\"></textarea>\r\n          <button class=\"flux-send-btn\" id=\"fluxAiSendBtn\" onclick=\"sendFluxAiMessage()\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><line x1=\"22\" y1=\"2\" x2=\"11\" y2=\"13\"/><polygon points=\"22 2 15 22 11 13 2 9 22 2\"/></svg>\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</div>\r\n\r\n<div class=\"flux-fullscreen\" id=\"fluxFullscreen\">\r\n  <div id=\"fluxFsListView\" style=\"display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden;\">\r\n    <div id=\"fluxFsSidebarHeader\" style=\"padding:14px 16px;display:flex;align-items:center;justify-content:space-between;background:#060000;flex-shrink:0;\">\r\n      <div id=\"fluxFsSidebarTitle\" style=\"font-size:15px;font-weight:600;display:flex;align-items:center;gap:8px;\">\r\n        Messages <span class=\"flux-secure-badge\">SECURE</span>\r\n      </div>\r\n      <button class=\"flux-close-btn\" onclick=\"closeFLUX()\">\u00d7</button>\r\n    </div>\r\n    <div class=\"flux-fs-search-wrap\">\r\n      <div class=\"flux-search-input-row\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"13\" height=\"13\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n        <input type=\"text\" id=\"fluxFsSearchInput\" placeholder=\"Search users...\" oninput=\"onFluxFsSearch(this.value)\" onkeydown=\"if(event.key==='Enter'){event.preventDefault();onFluxSearchEnter(this.value,'mobile');}\" autocomplete=\"off\">\r\n      </div>\r\n      <div class=\"flux-search-dropdown\" id=\"fluxFsSearchDropdown\"></div>\r\n    </div>\r\n    <div class=\"flux-tab-bar\" id=\"fluxFsTabBar\">\r\n      <button class=\"flux-tab-btn active\" data-tab=\"primary\" onclick=\"switchFluxTab('primary','mobile')\">Primary <span class=\"flux-tab-count\" id=\"fluxFsPrimaryCount\" data-zero=\"true\">0</span></button>\r\n      <button class=\"flux-tab-btn\" data-tab=\"general\" onclick=\"switchFluxTab('general','mobile')\">General <span class=\"flux-tab-count\" id=\"fluxFsGeneralCount\" data-zero=\"true\">0</span></button>\r\n      <button class=\"flux-tab-btn\" data-tab=\"all\" onclick=\"switchFluxTab('all','mobile')\">All</button>\r\n    </div>\r\n    <div class=\"flux-sidebar-load-bar\" id=\"fluxFsSidebarLoadBar\"><div class=\"flux-load-bar-fill\" id=\"fluxFsSidebarLoadFill\"></div></div>\r\n    <div class=\"flux-conv-list\" id=\"fluxFsConvList\" style=\"flex:1;overflow-y:auto;padding:8px;\"></div>\r\n  </div>\r\n  <div id=\"fluxFsRelayView\" style=\"display:none;flex-direction:column;flex:1;min-height:0;overflow:hidden;position:relative;\">\r\n    <div class=\"flux-clearing-overlay\" id=\"fluxFsClearingOverlay\">\r\n      <div class=\"flux-clearing-label\">Getting things done\u2026</div>\r\n      <div class=\"flux-clearing-bar-wrap\">\r\n        <div class=\"flux-clearing-bar-fill\" id=\"fluxFsClearingBarFill\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"flux-fs-header\">\r\n      <button class=\"flux-fs-back\" onclick=\"fluxFsBack()\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><polyline points=\"15 18 9 12 15 6\"/></svg>\r\n      </button>\r\n      <div style=\"position:relative;flex-shrink:0;cursor:pointer;\" onclick=\"openMobileProfileSheet()\">\r\n        <div class=\"flux-fs-avatar default-avatar\" id=\"fluxFsAvatar\"></div>\r\n        <span class=\"flux-presence-dot offline\" id=\"fluxFsPresenceDot\"></span>\r\n      </div>\r\n      <div style=\"flex:1;min-width:0;display:flex;flex-direction:column;justify-content:center;cursor:pointer;\" onclick=\"openMobileProfileSheet()\">\r\n        <div class=\"flux-fs-name\" id=\"fluxFsName\"></div>\r\n        <div id=\"fluxFsUsername\" style=\"font-size:11px;color:var(--text2);line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:1px;\"></div>\r\n      </div>\r\n      <button class=\"flux-group-mute-btn\" id=\"fluxFsGroupMuteBtn\" onclick=\"toggleActiveFluxGroupMute()\" title=\"Mute group\" aria-label=\"Mute group\">\r\n        <svg id=\"fluxFsGroupMuteIcon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n          <path d=\"M8.7 3A6 6 0 0 1 18 8c0 2.1.8 3.9 1.6 5.2\"/>\r\n          <path d=\"M17 17H3s3-2 3-9c0-.7.1-1.4.3-2\"/>\r\n          <path d=\"M10.3 21a1.94 1.94 0 0 0 3.4 0\"/>\r\n          <path d=\"m2 2 20 20\"/>\r\n        </svg>\r\n      </button>\r\n      <button class=\"flux-delete-relay-btn\" id=\"fluxFsDeleteRelayBtn\" onclick=\"handleFluxHeaderClear()\" title=\"Clear relay\" aria-label=\"Clear relay\" style=\"margin-left:auto;\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide-badge-x-icon\"><path d=\"M3.85 8.62a4 4 0 0 1 4.78-4.77 4 4 0 0 1 6.74 0 4 4 0 0 1 4.78 4.78 4 4 0 0 1 0 6.74 4 4 0 0 1-4.77 4.78 4 4 0 0 1-6.75 0 4 4 0 0 1-4.78-4.77 4 4 0 0 1 0-6.76Z\"/><line x1=\"15\" x2=\"9\" y1=\"9\" y2=\"15\"/><line x1=\"9\" x2=\"15\" y1=\"9\" y2=\"15\"/></svg>\r\n      </button>\r\n      <button class=\"flux-delete-relay-btn flux-group-menu-btn\" id=\"fluxFsHeaderMoreBtn\" onclick=\"openFluxHeaderMoreMenu(event)\" title=\"More options\" aria-label=\"More options\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"5\" r=\"1\"/><circle cx=\"12\" cy=\"19\" r=\"1\"/></svg>\r\n      </button>\r\n      <button class=\"flux-unarchive-btn\" id=\"fluxFsUnarchiveBtn\" onclick=\"confirmUnarchiveActive()\" title=\"Unarchive\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"5\" rx=\"1\"/><path d=\"M5 9v9a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V9\"/><polyline points=\"9 13 12 10 15 13\"/><line x1=\"12\" y1=\"10\" x2=\"12\" y2=\"17\"/></svg>\r\n      </button>\r\n    </div>\r\n\r\n    <div class=\"flux-fs-body\">\r\n    <div class=\"flux-relay-load-bar\" id=\"fluxFsRelayLoadBar\"><div class=\"flux-load-bar-fill\" id=\"fluxFsRelayLoadFill\"></div></div>\r\n    <div class=\"flux-fs-messages\" id=\"fluxFsMessages\"></div>\r\n\r\n    <div class=\"flux-fs-media-staging-wrap\" id=\"fluxFsMediaStagingWrap\">\r\n      <div class=\"flux-media-staging-inner\">\r\n        <div class=\"flux-media-staging-thumb\" id=\"fluxFsMediaStagingThumb\"></div>\r\n        <span style=\"font-size:12px;color:var(--text2);\">Image ready to send</span>\r\n      </div>\r\n      <button class=\"flux-reply-cancel\" onclick=\"clearFluxFsStaging()\" title=\"Remove image\">\u00d7</button>\r\n    </div>\r\n\r\n    <div class=\"flux-edit-bar\" id=\"fluxFsEditBar\">\r\n      <div class=\"flux-edit-bar-label\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"12\" height=\"12\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\r\n        Editing\r\n      </div>\r\n      <div class=\"flux-edit-bar-text\" id=\"fluxFsEditBarText\"></div>\r\n      <button class=\"flux-reply-cancel\" onclick=\"cancelEdit('mobile')\" title=\"Cancel edit\">\u00d7</button>\r\n    </div>\r\n\r\n    <div class=\"flux-reply-bar\" id=\"fluxFsReplyBar\">\r\n      <div style=\"display:flex;align-items:center;gap:6px;color:var(--accent);font-size:11.5px;font-weight:600;margin-bottom:2px;\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" width=\"12\" height=\"12\"><polyline points=\"9 17 4 12 9 7\"/><path d=\"M20 18v-2a4 4 0 0 0-4-4H4\"/></svg>\r\n        Replying to\r\n      </div>\r\n      <div class=\"flux-reply-bar-content\">\r\n        <div class=\"flux-reply-bar-author\" id=\"fluxFsReplyBarAuthor\"></div>\r\n        <div class=\"flux-reply-bar-text\" id=\"fluxFsReplyBarText\"></div>\r\n      </div>\r\n      <img class=\"flux-reply-bar-thumb\" id=\"fluxFsReplyBarThumb\" style=\"display:none;\" alt=\"\">\r\n      <button class=\"flux-reply-cancel\" onclick=\"cancelReply('mobile')\">\u00d7</button>\r\n    </div>\r\n\r\n\r\n    <div class=\"flux-fs-input-area\">\r\n      <div class=\"flux-fs-input-row\">\r\n        <button class=\"emoji-btn\" id=\"fluxFsEmojiBtn\" onclick=\"toggleEmojiPicker('mobile')\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" x2=\"9.01\" y1=\"9\" y2=\"9\"/><line x1=\"15\" x2=\"15.01\" y1=\"9\" y2=\"9\"/></svg>\r\n        </button>\r\n        <label class=\"emoji-btn\" for=\"fluxFsMediaUpload\" title=\"Send media\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\"/><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"/><polyline points=\"21 15 16 10 5 21\"/></svg>\r\n        </label>\r\n        <input type=\"file\" id=\"fluxFsMediaUpload\" accept=\"image/*,video/*\" style=\"display:none\" onchange=\"stageFluxMedia(event,'mobile')\">\r\n        <textarea id=\"fluxFsInput\" placeholder=\"Message\u2026\" oninput=\"onFluxInputChange('mobile'); toggleFluxFsSendBtn(); autoResizeFlux(this)\" onfocus=\"onFluxInputFocus('mobile')\" onblur=\"onFluxInputBlur('mobile')\" onkeydown=\"onFluxKeypress(event,'mobile'); fluxHandleKey(event,'mobile')\" onpaste=\"handleFluxPaste(event,'mobile')\" rows=\"1\"></textarea>\r\n        <button class=\"flux-send-btn\" id=\"fluxFsSendBtn\" onmousedown=\"event.preventDefault()\" ontouchend=\"event.preventDefault(); fluxSend('mobile')\" onclick=\"if(!('ontouchstart' in window)) fluxSend('mobile')\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><line x1=\"22\" y1=\"2\" x2=\"11\" y2=\"13\"/><polygon points=\"22 2 15 22 11 13 2 9 22 2\"/></svg>\r\n        </button>\r\n      </div>\r\n    </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- IMAGE LIGHTBOX -->\r\n<div class=\"lightbox\" id=\"lightbox\" onclick=\"if(event.target===this)closeLightbox()\">\r\n  <div class=\"lightbox-header\">\r\n    <button class=\"lightbox-icon-btn\" id=\"lightboxDownloadBtn\" onclick=\"lightboxDownloadCurrentImage()\" title=\"Download\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\r\n    </button>\r\n    <button class=\"lightbox-icon-btn\" id=\"lightboxReplyBtn\" onclick=\"lightboxReplyToCurrentImage()\" title=\"Reply\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"9 17 4 12 9 7\"/><path d=\"M20 18v-2a4 4 0 0 0-4-4H4\"/></svg>\r\n    </button>\r\n    <button class=\"lightbox-icon-btn\" id=\"lightboxDeleteBtn\" onclick=\"lightboxDeleteCurrentImage()\" style=\"display:none;\" title=\"Delete\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/><path d=\"M10 11v6\"/><path d=\"M14 11v6\"/><path d=\"M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2\"/></svg>\r\n    </button>\r\n    <button class=\"lightbox-icon-btn\" onclick=\"closeLightbox()\" title=\"Close\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"width:26px;height:26px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n    </button>\r\n  </div>\r\n  <div class=\"lightbox-body\" onclick=\"if(event.target===this)closeLightbox()\">\r\n    <button class=\"lightbox-nav-btn\" id=\"lightboxPrev\" onclick=\"lightboxStep(-1)\" style=\"display:none;\">\r\n      <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-chevron-left-icon lucide-chevron-left\"><path d=\"m15 18-6-6 6-6\"/></svg>\r\n    </button>\r\n    <img id=\"lightboxImg\" src=\"\" alt=\"\" style=\"cursor:default;\">\r\n    <button class=\"lightbox-nav-btn\" id=\"lightboxNext\" onclick=\"lightboxStep(1)\" style=\"display:none;\">\r\n      <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-chevron-right-icon lucide-chevron-right\"><path d=\"m9 18 6-6-6-6\"/></svg>\r\n    </button>\r\n  </div>\r\n  <div class=\"lightbox-footer\" id=\"lightboxFooter\" style=\"display:none;\" onclick=\"if(event.target===this)closeLightbox()\">\r\n    <span class=\"lightbox-counter\" id=\"lightboxCounter\"></span>\r\n    <div class=\"lightbox-strip\" id=\"lightboxStrip\"></div>\r\n  </div>\r\n</div>\r\n\r\n<!-- EMOJI PICKER -->\r\n<div class=\"emoji-picker-overlay\" id=\"emojiPickerOverlay\" onclick=\"closeEmojiPicker()\"></div>\r\n<div class=\"emoji-picker\" id=\"emojiPicker\"></div>\r\n\r\n<!-- Context menu (right-click) -->\r\n<div class=\"flux-ctx-menu\" id=\"fluxCtxMenu\" style=\"display:none;\"></div>\r\n\r\n<div class=\"flux-msg-action-menu\" id=\"fluxMsgActionMenu\"></div>\r\n<div class=\"flux-conv-menu\" id=\"fluxConvMenu\"></div>\r\n<div class=\"flux-conv-menu\" id=\"fluxHeaderMoreMenu\"></div>\r\n<div class=\"flux-conv-menu\" id=\"fluxGroupAvatarMenu\"></div>\r\n<input type=\"file\" id=\"fluxGroupAvatarUpload\" accept=\"image/*\" style=\"display:none\" onchange=\"handleGroupAvatarUpload(event)\">\r\n\r\n<!-- AVATAR CROP MODAL -->\r\n<div class=\"overlay\" id=\"avatarCropOverlay\" style=\"z-index:500;\">\r\n  <div class=\"avatar-crop-modal\" id=\"avatarCropModal\">\r\n    <div class=\"acm-header\">\r\n      <span class=\"acm-title\">Crop photo</span>\r\n    </div>\r\n\r\n    <!-- Crop stage -->\r\n    <div class=\"acm-canvas-wrap\" id=\"acmCanvasWrap\">\r\n      <canvas id=\"acmCanvas\"></canvas>\r\n\r\n      <!-- Dim panels outside crop box -->\r\n      <div class=\"acm-dim\" id=\"acmDimTop\"></div>\r\n      <div class=\"acm-dim\" id=\"acmDimBottom\"></div>\r\n      <div class=\"acm-dim\" id=\"acmDimLeft\"></div>\r\n      <div class=\"acm-dim\" id=\"acmDimRight\"></div>\r\n\r\n      <!-- Dashed crop box -->\r\n      <div id=\"acmCropBox\" style=\"position:absolute;border:2px dashed rgba(255,255,255,0.90);box-sizing:border-box;pointer-events:none;\">\r\n        <!-- Rule-of-thirds grid -->\r\n        <div style=\"position:absolute;top:33.33%;left:0;width:100%;height:1px;background:rgba(255,255,255,0.18);pointer-events:none;\"></div>\r\n        <div style=\"position:absolute;top:66.66%;left:0;width:100%;height:1px;background:rgba(255,255,255,0.18);pointer-events:none;\"></div>\r\n        <div style=\"position:absolute;left:33.33%;top:0;height:100%;width:1px;background:rgba(255,255,255,0.18);pointer-events:none;\"></div>\r\n        <div style=\"position:absolute;left:66.66%;top:0;height:100%;width:1px;background:rgba(255,255,255,0.18);pointer-events:none;\"></div>\r\n        <!-- Circle ring inside crop box -->\r\n        <div id=\"acmCropCircle\" style=\"position:absolute;border-radius:50%;border:2px solid rgba(255,255,255,0.75);box-sizing:border-box;pointer-events:none;\"></div>\r\n      </div>\r\n\r\n      <!-- Corner handles (draggable) -->\r\n      <div class=\"acm-handle acm-corner-handle\" id=\"acmHtl\" data-handle=\"tl\" style=\"top:0;left:0;cursor:nw-resize;\"></div>\r\n      <div class=\"acm-handle acm-corner-handle\" id=\"acmHtr\" data-handle=\"tr\" style=\"top:0;right:0;cursor:ne-resize;\"></div>\r\n      <div class=\"acm-handle acm-corner-handle\" id=\"acmHbl\" data-handle=\"bl\" style=\"bottom:0;left:0;cursor:sw-resize;\"></div>\r\n      <div class=\"acm-handle acm-corner-handle\" id=\"acmHbr\" data-handle=\"br\" style=\"bottom:0;right:0;cursor:se-resize;\"></div>\r\n\r\n      <!-- Edge handles (draggable) -->\r\n      <div class=\"acm-handle acm-edge-handle\" id=\"acmHt\"  data-handle=\"t\"  style=\"top:0;left:50%;transform:translateX(-50%);cursor:n-resize;\"></div>\r\n      <div class=\"acm-handle acm-edge-handle\" id=\"acmHb\"  data-handle=\"b\"  style=\"bottom:0;left:50%;transform:translateX(-50%);cursor:s-resize;\"></div>\r\n      <div class=\"acm-handle acm-edge-handle\" id=\"acmHl\"  data-handle=\"l\"  style=\"left:0;top:50%;transform:translateY(-50%);cursor:w-resize;\"></div>\r\n      <div class=\"acm-handle acm-edge-handle\" id=\"acmHr\"  data-handle=\"r\"  style=\"right:0;top:50%;transform:translateY(-50%);cursor:e-resize;\"></div>\r\n    </div>\r\n\r\n    <!-- Preview + action buttons -->\r\n    <div class=\"acm-bottom-bar\">\r\n      <div class=\"acm-preview-wrap\">\r\n        <canvas id=\"acmPreviewCanvas\" width=\"52\" height=\"52\" class=\"acm-preview-canvas\"></canvas>\r\n      </div>\r\n      <div class=\"acm-actions\">\r\n        <button class=\"btn-cancel\" onclick=\"closeCropModal()\">Cancel</button>\r\n        <button class=\"btn-confirm acm-save-btn\" id=\"acmApplyBtn\">Save</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"overlay\" id=\"vaultOverlay\">\r\n  <div class=\"popup\">\r\n    <h3>Admin Key</h3>\r\n    <p>Enter your operator key to continue.</p>\r\n    <input type=\"text\" id=\"vaultInput\" name=\"vault-key-field\" autocomplete=\"off\" autocorrect=\"off\" autocapitalize=\"off\" spellcheck=\"false\" placeholder=\"Enter administration key\" onkeydown=\"vaultKeyHandler(event)\">\r\n    <div class=\"popup-error\" id=\"vaultError\">Incorrect key. Try again.</div>\r\n    <div class=\"popup-btns\">\r\n      <button class=\"btn-cancel\" onclick=\"closeVaultPopup()\">Cancel</button>\r\n      <button class=\"btn-confirm\" id=\"vaultVerifyBtn\" onclick=\"verifyVault()\"><span id=\"vaultVerifyLabel\">Verify</span><span id=\"vaultVerifySpinner\" class=\"spinner\" style=\"display:none;\"></span></button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- PROFILE DETAILS POPUP -->\r\n<div class=\"overlay\" id=\"profileEditOverlay\">\r\n  <div class=\"pdp-popup\">\r\n    <div class=\"pdp-header\">\r\n      <h3>Profile details</h3>\r\n      <button class=\"pdp-close\" onclick=\"closeProfileEdit()\" aria-label=\"Close\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n      </button>\r\n    </div>\r\n    <div class=\"pdp-body\">\r\n      <div class=\"pdp-avatar-wrap\" onclick=\"openAvatarPicker()\" title=\"Change profile picture\">\r\n        <div class=\"pdp-avatar default-avatar\" id=\"pdpAvatar\"></div>\r\n        <div class=\"pdp-avatar-overlay\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.3 20H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.98a2 2 0 0 1 1.69.9l.66 1.2A2 2 0 0 0 12 6h8a2 2 0 0 1 2 2v3.3\"/><path d=\"m14.305 19.53.923-.382\"/><path d=\"m15.228 16.852-.923-.383\"/><path d=\"m16.852 15.228-.383-.923\"/><path d=\"m16.852 20.772-.383.924\"/><path d=\"m19.148 15.228.383-.923\"/><path d=\"m19.53 21.696-.382-.924\"/><path d=\"m20.772 16.852.924-.383\"/><path d=\"m20.772 19.148.924.383\"/><circle cx=\"18\" cy=\"18\" r=\"3\"/></svg>\r\n        </div>\r\n      </div>\r\n      <div class=\"pdp-input-col\">\r\n        <input type=\"text\" class=\"pdp-input\" id=\"pdpDisplayName\" placeholder=\"Add a name\" maxlength=\"40\">\r\n        <a class=\"pdp-remove-link\" onclick=\"removeAvatar()\">Remove photo</a>\r\n      </div>\r\n    </div>\r\n    <div class=\"pdp-footer\">\r\n      <button class=\"pdp-save-btn\" onclick=\"saveProfileDetails()\">Save</button>\r\n    </div>\r\n    <div class=\"pdp-disclaimer\">By proceeding, you agree to give hether access to the image you choose to upload. Please make sure you have the right to upload the image.</div>\r\n  </div>\r\n</div>\r\n\r\n<!-- FLUX GROUP SETTINGS POPUP -->\r\n<div class=\"overlay\" id=\"fluxGroupSettingsOverlay\" style=\"z-index:20010;\">\r\n  <div class=\"pdp-popup flux-group-settings-popup\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"fluxGroupSettingsTitle\">\r\n    <div class=\"pdp-header\">\r\n      <h3 id=\"fluxGroupSettingsTitle\">Group settings</h3>\r\n      <button class=\"pdp-close\" onclick=\"closeFluxGroupSettings()\" aria-label=\"Close\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n      </button>\r\n    </div>\r\n    <div class=\"fgs-body\">\r\n      <div class=\"fgs-row\"><div><div class=\"fgs-label\">Members can change group icon</div><div class=\"fgs-sub\">Allow non-admin members to change the group photo.</div></div><button type=\"button\" class=\"fgs-toggle\" id=\"fgsChangePfpToggle\" onclick=\"toggleFluxGroupSetting('allow_members_change_pfp', this)\" aria-label=\"Members can change group icon\"></button></div>\r\n      <div class=\"fgs-row\"><div><div class=\"fgs-label\">Members can change group name</div><div class=\"fgs-sub\">Allow non-admin members to rename the group.</div></div><button type=\"button\" class=\"fgs-toggle\" id=\"fgsChangeNameToggle\" onclick=\"toggleFluxGroupSetting('allow_members_change_name', this)\" aria-label=\"Members can change group name\"></button></div>\r\n      <div class=\"fgs-row\"><div><div class=\"fgs-label\">Non-admins can clear all</div><div class=\"fgs-sub\">Allow non-admin members to clear all group messages. Off by default.</div></div><button type=\"button\" class=\"fgs-toggle\" id=\"fgsClearAllToggle\" onclick=\"toggleFluxGroupSetting('allow_non_admin_clear_all', this)\" aria-label=\"Non-admins can clear all\"></button></div>\r\n      <div class=\"fgs-row\"><div><div class=\"fgs-label\">Non-admins can add members</div><div class=\"fgs-sub\">Allow non-admin members to add people to the group.</div></div><button type=\"button\" class=\"fgs-toggle\" id=\"fgsAddMembersToggle\" onclick=\"toggleFluxGroupSetting('allow_non_admin_add_members', this)\" aria-label=\"Non-admins can add members\"></button></div>\r\n    </div>\r\n    <div class=\"pdp-disclaimer\" style=\"margin-top:20px;color:#a7a7a7;font-weight:400;\">Only group admins can change these settings.</div>\r\n  </div>\r\n</div>\r\n\r\n<!-- LOG OUT CONFIRM -->\r\n<div class=\"overlay\" id=\"logoutOverlay\">\r\n  <div class=\"popup\">\r\n    <h3>Log out?</h3>\r\n    <p>You'll be signed out of your account on this device.</p>\r\n    <div class=\"popup-btns\">\r\n      <button class=\"btn-cancel\" onclick=\"closeLogout()\">Cancel</button>\r\n      <button class=\"btn-confirm\" style=\"background:#ef4444;\" onclick=\"confirmLogout()\">Log out</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- FLUX ARCHIVE SECRET SETUP \u2014 STEP 1 -->\r\n<div class=\"overlay\" id=\"fluxArchiveSecretOverlay\" style=\"z-index: 20000;\">\r\n  <div class=\"pdp-popup flux-archive-secret-popup\" id=\"fluxArchiveSecretPopup\">\r\n    <div class=\"pdp-header\">\r\n      <h3>Create secret key</h3>\r\n      <button class=\"pdp-close\" onclick=\"closeFluxArchiveSecretSetup()\" aria-label=\"Close\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n      </button>\r\n    </div>\r\n    <div class=\"flux-archive-secret-body\">\r\n      <p>Create a secret key to protect your archived chats. You will need this key to reveal them from Flux search.</p>\r\n      <input id=\"fluxArchiveSecretInput\" class=\"pdp-input flux-archive-secret-input\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Secret key\">\r\n      <div id=\"fluxArchiveSecretError\" style=\"display:none;color:#ef4444;font-size:12px;margin:0 0 12px;\"></div>\r\n    </div>\r\n    <div class=\"pdp-footer flux-archive-secret-footer\">\r\n      <button class=\"btn-cancel\" onclick=\"closeFluxArchiveSecretSetup()\">Cancel</button>\r\n      <button class=\"pdp-save-btn\" id=\"fluxArchiveSecretCreateBtn\" onclick=\"submitFluxArchiveSecretSetup()\">Next</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- FLUX ARCHIVE SECRET SETUP \u2014 STEP 2 -->\r\n<div class=\"overlay\" id=\"fluxArchiveSecretConfirmOverlay\" style=\"z-index: 20001;\">\r\n  <div class=\"pdp-popup flux-archive-secret-popup\" id=\"fluxArchiveSecretConfirmPopup\">\r\n    <div class=\"pdp-header\">\r\n      <h3>Confirm secret key</h3>\r\n      <button class=\"pdp-close\" onclick=\"closeFluxArchiveSecretSetup()\" aria-label=\"Close\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n      </button>\r\n    </div>\r\n    <div class=\"flux-archive-secret-body\">\r\n      <p>Enter the same secret key again to confirm it.</p>\r\n      <input id=\"fluxArchiveSecretConfirm\" class=\"pdp-input flux-archive-secret-input\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Confirm secret key\">\r\n      <div id=\"fluxArchiveSecretConfirmError\" style=\"display:none;color:#ef4444;font-size:12px;margin:0 0 12px;\"></div>\r\n    </div>\r\n    <div class=\"pdp-footer flux-archive-secret-footer\">\r\n      <button class=\"btn-cancel\" onclick=\"closeFluxArchiveSecretSetup()\">Cancel</button>\r\n      <button class=\"pdp-save-btn\" onclick=\"submitFluxArchiveSecretConfirm()\">Confirm</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- FLUX FOLDER KEY CHANGE \u2014 STEP 1: CURRENT KEY -->\r\n<div class=\"overlay\" id=\"fluxFolderKeyOverlay\" style=\"z-index: 20002;\">\r\n  <div class=\"pdp-popup flux-archive-secret-popup\" id=\"fluxFolderKeyPopup\">\r\n    <div class=\"pdp-header\"><h3>Folder key</h3><button class=\"pdp-close\" onclick=\"closeFluxFolderKeyChange()\" aria-label=\"Close\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div>\r\n    <div class=\"flux-archive-secret-body\"><p>Enter your current folder key.</p><input id=\"fluxFolderKeyCurrent\" class=\"pdp-input flux-archive-secret-input\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Current key\"><div id=\"fluxFolderKeyCurrentError\" style=\"display:none;color:#ef4444;font-size:12px;margin:0 0 12px;\"></div></div>\r\n    <div class=\"pdp-footer flux-archive-secret-footer\"><button class=\"btn-cancel\" onclick=\"closeFluxFolderKeyChange()\">Cancel</button><button class=\"pdp-save-btn\" onclick=\"submitFluxFolderKeyCurrent()\">Next</button></div>\r\n  </div>\r\n</div>\r\n\r\n<!-- FLUX FOLDER KEY CHANGE \u2014 STEP 2: CREATE NEW KEY -->\r\n<div class=\"overlay\" id=\"fluxFolderKeyNewOverlay\" style=\"z-index: 20003;\">\r\n  <div class=\"pdp-popup flux-archive-secret-popup\" id=\"fluxFolderKeyNewPopup\">\r\n    <div class=\"pdp-header\"><h3>Create new secret key</h3><button class=\"pdp-close\" onclick=\"closeFluxFolderKeyChange()\" aria-label=\"Close\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div>\r\n    <div class=\"flux-archive-secret-body\"><p>Create a new secret key for your archived chats.</p><input id=\"fluxFolderKeyNew\" class=\"pdp-input flux-archive-secret-input\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Secret key\"><div id=\"fluxFolderKeyNewError\" style=\"display:none;color:#ef4444;font-size:12px;margin:0 0 12px;\"></div></div>\r\n    <div class=\"pdp-footer flux-archive-secret-footer\"><button class=\"btn-cancel\" onclick=\"closeFluxFolderKeyChange()\">Cancel</button><button class=\"pdp-save-btn\" onclick=\"submitFluxFolderKeyNew()\">Next</button></div>\r\n  </div>\r\n</div>\r\n\r\n<!-- FLUX FOLDER KEY CHANGE \u2014 STEP 3: CONFIRM NEW KEY -->\r\n<div class=\"overlay\" id=\"fluxFolderKeyConfirmOverlay\" style=\"z-index: 20004;\">\r\n  <div class=\"pdp-popup flux-archive-secret-popup\" id=\"fluxFolderKeyConfirmPopup\">\r\n    <div class=\"pdp-header\"><h3>Confirm secret key</h3><button class=\"pdp-close\" onclick=\"closeFluxFolderKeyChange()\" aria-label=\"Close\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div>\r\n    <div class=\"flux-archive-secret-body\"><p>Enter the same new secret key again to confirm it.</p><input id=\"fluxFolderKeyConfirm\" class=\"pdp-input flux-archive-secret-input\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Confirm secret key\"><div id=\"fluxFolderKeyConfirmError\" style=\"display:none;color:#ef4444;font-size:12px;margin:0 0 12px;\"></div></div>\r\n    <div class=\"pdp-footer flux-archive-secret-footer\"><button class=\"btn-cancel\" onclick=\"closeFluxFolderKeyChange()\">Cancel</button><button class=\"pdp-save-btn\" onclick=\"submitFluxFolderKeyConfirm()\">Confirm</button></div>\r\n  </div>\r\n</div>\r\n\r\n<!-- CONFIRM DIALOG OVERLAY -->\r\n<div class=\"overlay\" id=\"confirmOverlay\">\r\n  <div class=\"confirm-popup\" id=\"confirmPopup\">\r\n    <h3 id=\"confirmTitle\">Are you sure?</h3>\r\n    <p id=\"confirmMsg\">This action cannot be undone.</p>\r\n    <div class=\"popup-btns\">\r\n      <button class=\"btn-cancel\" onclick=\"closeConfirm()\">Cancel</button>\r\n      <button class=\"btn-confirm\" id=\"confirmOkBtn\" style=\"background:#ef4444;\" onclick=\"confirmAction()\">Confirm</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"clear-relay-overlay\" id=\"clearRelayOverlay\">\r\n  <div class=\"confirm-popup\" id=\"clearRelayPopup\">\r\n    <h3>Clear all?</h3>\r\n    <p>All messages in this conversation will be permanently deleted for both people. This cannot be undone.</p>\r\n    <div class=\"popup-btns\">\r\n      <button class=\"btn-cancel\" id=\"clearRelayCancelBtn\" onclick=\"closeClearRelayConfirm()\">Cancel</button>\r\n      <button class=\"btn-confirm\" id=\"clearRelayConfirmBtn\" style=\"background:#ef4444;\" onclick=\"confirmClearRelay()\">Clear</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n</div><!-- /mainApp -->\r\n\r\n<div id=\"terminalOverlay\" onclick=\"closeVaultTerminal()\"></div>\r\n<div id=\"vaultTerminal\" role=\"dialog\" aria-label=\"Vault Terminal\">\r\n  <div class=\"term-titlebar\">\r\n    <div class=\"term-titlebar-left\">\r\n      <div class=\"term-title\">hether :: vault-shell</div>\r\n    </div>\r\n    <button class=\"term-close\" onclick=\"closeVaultTerminal()\" title=\"Close (Esc)\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\r\n    </button>\r\n  </div>\r\n  <div id=\"termBody\" onclick=\"focusTermInput()\">\r\n    <!-- output lines injected here by JS -->\r\n    <div class=\"term-input-line\">\r\n      <span class=\"term-prompt-sym\">&gt;&gt;</span>\r\n      <input id=\"termLiveInput\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" onkeydown=\"termHandleKey(event)\">\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- SNIPPETS (no mini widget needed) -->\r\n\r\n");
